    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('鶏', 'ケイ', 'にわとり', 'niwatori', 'KÊ', 'gà gáy buổi sáng sớm, trứng gà', 17, '鳥 -> 夫 -> 爫', '鳥', '早朝に鶏が鳴く (そうちょうににわとりがなく: gà gáy buổi sáng sớm)、鶏卵 (けいらん: trứng gà)、養鶏場 (ようけいじょう: trang trại nuôi gà)、闘鶏 (とうけい: gà chọi)', '早朝に鶏が鳴く（そうちょうににわとりがなく）', 'souchouniniwatoriganaku', 'gà gáy buổi sáng sớm', 'N1', 'Chiết tự Hán Việt: KÊ (鶏)', 'GÀ（鶏） là một loài CHIM（鳥） mà con trống（夫） có mào lớn（爫） trên đầu', '⚒️', v_ch6_id, 41, NULL, NOW())
