    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('冒', 'キケ', 'おか.す, おか.される', 'okasu', 'MẠO', 'đương đầu với nguy hiểm, chống chọi với bệnh tật', 14, '目 -> 日', '目', '危険を冒す (きけんをおかす: đương đầu với nguy hiểm)、病に冒される (やまいにおかされる: chống chọi với bệnh tật)、冒険心 (ぼうけんしん: tính phiêu lưu)、総合感冒薬 (そうごうかんぼうやく: tổng hợp các loại thuốc cảm cúm)', '危険を冒す（きけんをおかす）', 'kikenookasu', 'đương đầu với nguy hiểm', 'N1', 'Chiết tự Hán Việt: MẠO (冒)', 'Mắt (目) nhìn trực tiếp mặt trời (日) thì MẠO hiểm quá', '⛩️', v_ch16_id, 10, NULL, NOW())
