    INSERT INTO kanjis (character, on_reading, kun_reading, romaji, han_viet, meaning, stroke_count, stroke_guide, radical, related_words, example_sentence, example_romaji, example_meaning, jlpt_level, mnemonic_title, mnemonic_hint, mnemonic_icon, chapter_id, chapter_order, image_url, created_at) VALUES
    ('撤', 'テッ', '', 'te', 'TRIỆT', 'thu hồi, rút lại lời nói trước đây', 17, '扌 -> 攵 -> 育', '扌', '撤去する (てっきょする: thu hồi, tháo dỡ)、前言を撤回する (ぜんげんをてっかいする: rút lại lời nói trước đây)、撤収 (てっしゅう: rút quân)、撤退する (てったいする: rút lui)', '撤去する（てっきょする）', 'tekkyosuru', 'thu hồi, tháo dỡ', 'N1', 'Chiết tự Hán Việt: TRIỆT (撤)', 'Phải dùng Tay (扌) Đánh khẽ (攵) thì mới giáo Dục (育 ) TRIỆTđể được những đứa trẻ hư', '⛩️', v_ch16_id, 16, NULL, NOW())
