-- 3. SEED HƠN 3.500 TỪ VỰNG HỌC THUẬT, BÁO CHÍ & THÀNH NGỮ 4 CHỮ (YOJIJUKUGO)
DO $$
DECLARE v_ch_id BIGINT; BEGIN
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 1;
    IF v_ch_id IS NOT NULL THEN
        DELETE FROM kanji_chapter_vocab WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_chapter_vocab (chapter_id, word, reading, romaji, meaning_vi, meaning_en, display_order, created_at) VALUES
        (v_ch_id, '行為', 'こうい', 'koui', 'Hành vi', 'Vi — Hành vi', 1, NOW()),
        (v_ch_id, '不正行為', 'ふせいこうい', 'fuseikoui', 'Hành vi bất chính', 'Vi — Hành vi bất chính', 2, NOW()),
        (v_ch_id, '扱う', 'あつかう', 'atsukau', 'Xử lý, đối xử, sử dụng', 'Tráp — Xử lý, đối xử, sử dụng', 3, NOW()),
        (v_ch_id, '取扱説明書', 'とりあつかいせつめいしょ', 'toriatsukaisetsumeisho', 'Sách hướng dẫn sử dụng', 'Tráp — Sách hướng dẫn sử dụng', 4, NOW()),
