        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[胎児]」trong ngữ cảnh: (thai nhi)', '胎児', 'たいじ', '["たいじ", "びょうきとたたかう", "くにのかんかつ", "しゃちょうのひしょ"]', '「胎児」đọc là「たいじ」(taiji) — Nghĩa: thai nhi.', 1, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[胎教]」trong ngữ cảnh: (chăm sóc trong thời kỳ mang thai)', '胎教', 'たいきょう', '["せいみつけんさ", "ぎしんあんき", "じこうのあいさつをのべる", "たいきょう"]', '「胎教」đọc là「たいきょう」(taikyou) — Nghĩa: chăm sóc trong thời kỳ mang thai.', 2, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[胎動]」trong ngữ cảnh: (thai nhi đạp bụng mẹ)', '胎動', 'たいどう', '["おんしんびょうどう", "こうそくする", "たいどう", "こくそする"]', '「胎動」đọc là「たいどう」(taidou) — Nghĩa: thai nhi đạp bụng mẹ.', 3, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[角を矯めて牛を殺す]」trong ngữ cảnh: (“lợn lành chữa thành lợn què”)', '角を矯めて牛を殺す', 'かくをためてうしをころす', '["こえだめ", "かくをためてうしをころす", "れいぎただしい", "きたえる"]', '「角を矯めて牛を殺す」đọc là「かくをためてうしをころす」(kakuotameteushiokorosu) — Nghĩa: “lợn lành chữa thành lợn què”.', 4, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[矯正する]」trong ngữ cảnh: (niềng răng)', '矯正する', 'きょうせいする', '["きょうせいする", "じっしする", "ろうすい", "そしする"]', '「矯正する」đọc là「きょうせいする」(kyouseisuru) — Nghĩa: niềng răng.', 5, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[消耗品]」trong ngữ cảnh: (hàng hóa tiêu hao)', '消耗品', 'しょうもうひん', '["せっしやくわん", "べんかい", "れんきんじゅつ", "しょうもうひん"]', '「消耗品」đọc là「しょうもうひん」(shoumouhin) — Nghĩa: hàng hóa tiêu hao.', 6, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[消耗する]」trong ngữ cảnh: (tiêu hao)', '消耗する', 'しょうもうする', '["じんつう", "しょうげき", "しょうもうする", "クマにおそわれる"]', '「消耗する」đọc là「しょうもうする」(shoumousuru) — Nghĩa: tiêu hao.', 7, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[心神耗弱]」trong ngữ cảnh: (trí não chậm phát triển)', '心神耗弱', 'しんしんこうじゃく', '["さっかしょう", "しんしんこうじゃく", "しんぎする", "しょるいしんさ"]', '「心神耗弱」đọc là「しんしんこうじゃく」(shinshinkoujaku) — Nghĩa: trí não chậm phát triển.', 8, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[摩耗したダイヤ]」trong ngữ cảnh: (lốp xe đã bị mòn)', '摩耗したダイヤ', 'まもうしたダイヤ', '["まもうしたダイヤ", "こくれんけんしょう", "にっぽんこくけんぽう", "ほうきする"]', '「摩耗したダイヤ」đọc là「まもうしたダイヤ」(mamoushitadaiya) — Nghĩa: lốp xe đã bị mòn.', 9, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[鍛える]」trong ngữ cảnh: (rèn luyện)', '鍛える', 'きたえる', '["さぎし", "けいざいのはってんをそがいする", "さぎざい", "きたえる"]', '「鍛える」đọc là「きたえる」(kitaeru) — Nghĩa: rèn luyện.', 10, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[鍛造業]」trong ngữ cảnh: (ngành công nghiệp rèn, đúc)', '鍛造業', 'たんぞうぎょう', '["じんとうしき", "しょうとつ", "たんぞうぎょう", "さぎざい"]', '「鍛造業」đọc là「たんぞうぎょう」(tanzougyou) — Nghĩa: ngành công nghiệp rèn, đúc.', 11, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[鍛冶屋]」trong ngữ cảnh: (lò rèn)', '鍛冶屋', 'かじや', '["だんちょうのおもい", "かじや", "さんぎょうはいきぶつ", "けんぽうきねんび"]', '「鍛冶屋」đọc là「かじや」(kajiya) — Nghĩa: lò rèn.', 12, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[精錬する]」trong ngữ cảnh: (tinh luyện)', '精錬する', 'せいれんする', '["せいれんする", "こうそくじかん", "かんがいむりょう", "みっしゅうする"]', '「精錬する」đọc là「せいれんする」(seirensuru) — Nghĩa: tinh luyện.', 13, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[鍛錬する]」trong ngữ cảnh: (rèn luyện)', '鍛錬する', 'たんれんする', '["はいきする", "まもうしたダイヤ", "けんじょうご", "たんれんする"]', '「鍛錬する」đọc là「たんれんする」(tanrensuru) — Nghĩa: rèn luyện.', 14, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[錬金術]」trong ngữ cảnh: (thuật luyện kim)', '錬金術', 'れんきんじゅつ', '["くふうをこらす", "あいさつする", "れんきんじゅつ", "かたがこる"]', '「錬金術」đọc là「れんきんじゅつ」(renkinjutsu) — Nghĩa: thuật luyện kim.', 15, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[THAI]」(thai nhi, chăm sóc trong thời kỳ mang thai) — Mẹo nhớ: Chị Nguyệt có THAI với anh Đài?', 'THAI', '胎', '["矯", "耗", "鍛", "胎"]', 'Chữ「胎」(THAI) — thai nhi, chăm sóc trong thời kỳ mang thai. Từ tiêu biểu: 胎児（たいじ）.', 16, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[KIỂU]」(“lợn lành chữa thành lợn què”, niềng răng) — Mẹo nhớ: thúy Kiều chỉ thích KIỂU trai Thẳng như Mũi tên thôi?', 'KIỂU', '矯', '["錬", "殖", "矯", "鍛"]', 'Chữ「矯」(KIỂU) — “lợn lành chữa thành lợn què”, niềng răng. Từ tiêu biểu: 角を矯めて牛を殺す（かくをためてうしをころす）.', 17, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[MAO]」(hàng hóa tiêu hao, tiêu hao) — Mẹo nhớ: ông MAO phạm lỗi làm hao tài tốn của?', 'MAO', '耗', '["肥", "耗", "殖", "摂"]', 'Chữ「耗」(MAO) — hàng hóa tiêu hao, tiêu hao. Từ tiêu biểu: 消耗品（しょうもうひん）.', 18, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[ĐOÁN]」(rèn luyện, ngành công nghiệp rèn) — Mẹo nhớ: tôi ĐOÁN là muốn làm ra 1 sợi dây Vàng thì phải qua nhiều công Đoạn?', 'ĐOÁN', '鍛', '["鍛", "肥", "凝", "衰"]', 'Chữ「鍛」(ĐOÁN) — rèn luyện, ngành công nghiệp rèn. Từ tiêu biểu: 鍛える（きたえる）.', 19, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[LUYỆN]」(tinh luyện, rèn luyện) — Mẹo nhớ: Vàng đc tinh LUYỆN ở phía đông?', 'LUYỆN', '錬', '["衰", "秘", "密", "錬"]', 'Chữ「錬」(LUYỆN) — tinh luyện, rèn luyện. Từ tiêu biểu: 精錬する（せいれんする）.', 20, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[THỰC]」(tăng lên, làm tăng) — Mẹo nhớ: Cái chết 歹 trực tiếp 直 là do THỰC dân gây ra?', 'THỰC', '殖', '["摩", "擦", "殖", "密"]', 'Chữ「殖」(THỰC) — tăng lên, làm tăng. Từ tiêu biểu: 殖える（ふえる）.', 21, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[NHIẾP]」(hấp thụ, giữ gìn vệ sinh) — Mẹo nhớ: Tay vén tai NHIẾP ảnh gia lên thấy tiếp 4 đường?', 'NHIẾP', '摂', '["衝", "摂", "擦", "施"]', 'Chữ「摂」(NHIẾP) — hấp thụ, giữ gìn vệ sinh. Từ tiêu biểu: 摂取する（せっしゅする）.', 22, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[PHÌ]」(am hiểu, hầm chứa phân) — Mẹo nhớ: Chị nguyệt béo PHÌ màu 色 mỡ?', 'PHÌ', '肥', '["肥", "衝", "弁", "訴"]', 'Chữ「肥」(PHÌ) — am hiểu, hầm chứa phân. Từ tiêu biểu: 目が肥える（めがこえる）.', 23, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[NGƯNG]」(say mê golf, đau mỏi cứng vai) — Mẹo nhớ: NGHI(疑) ngờ do trời lạnh mà hơi nước bị NGƯNG(凝) tụ thành BĂNG(冫)?', 'NGƯNG', '凝', '["訴", "訟", "審", "凝"]', 'Chữ「凝」(NGƯNG) — say mê golf, đau mỏi cứng vai. Từ tiêu biểu: ゴルフに凝る（ゴルフにこる）.', 24, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[SUY]」(thể lực sa sút, suy nhược) — Mẹo nhớ: mắc covid nên SUY yếu phải đội mũ đeo khẩu trang và mặc quần áo kín mít?', 'SUY', '衰', '["償", "執", "衰", "審"]', 'Chữ「衰」(SUY) — thể lực sa sút, suy nhược. Từ tiêu biểu: 体力が衰える（たいりょくがおとろえる）.', 25, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 12;
    IF v_ch_id IS NOT NULL THEN
        DELETE FROM kanji_exercises WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[謙遜する]」trong ngữ cảnh: (khiêm tốn)', '謙遜する', 'けんそんする', '["けんそんする", "きおくそうしつ", "ふか", "おうしゅう"]', '「謙遜する」đọc là「けんそんする」(kensonsuru) — Nghĩa: khiêm tốn.', 1, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[遜色がない]」trong ngữ cảnh: (không kém hơn, không thấp hơn)', '遜色がない', 'そんしょくがない', '["もにふくする", "よいのみょうじょう", "しゅぶそくとう", "そんしょくがない"]', '「遜色がない」đọc là「そんしょくがない」(sonshokuganai) — Nghĩa: không kém hơn, không thấp hơn.', 2, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[不遜な態度]」trong ngữ cảnh: (thái độ ngạo mạn)', '不遜な態度', 'ふそんなたいど', '["けたちがいのやすさ", "さんけたのけいさんをする", "ふそんなたいど", "じゅだくする"]', '「不遜な態度」đọc là「ふそんなたいど」(fusonnataido) — Nghĩa: thái độ ngạo mạn.', 3, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[淘汰する]」trong ngữ cảnh: (loại bỏ)', '淘汰する', 'とうたする', '["しゅさいする", "とうたする", "しゅうせいかしょ", "るいせきあかじ"]', '「淘汰する」đọc là「とうたする」(toutasuru) — Nghĩa: loại bỏ.', 4, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[自然淘汰]」trong ngữ cảnh: (đào thải tự nhiên)', '自然淘汰', 'しぜんとうた', '["しぜんとうた", "はつもうで", "けんやくする", "ふうさいがあがらない"]', '「自然淘汰」đọc là「しぜんとうた」(shizentouta) — Nghĩa: đào thải tự nhiên.', 5, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[ご無沙汰しております]」trong ngữ cảnh: (đã lâu không gặp)', 'ご無沙汰しております', 'ごぶさたしております', '["ふうさいがあがらない", "たんしんふにん", "とむらう", "ごぶさたしております"]', '「ご無沙汰しております」đọc là「ごぶさたしております」(gobusatashiteorimasu) — Nghĩa: đã lâu không gặp.', 6, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[畏れる]」trong ngữ cảnh: (sợ hãi)', '畏れる', 'おそれる', '["てんぷ", "にょらいぞう", "おそれる", "かへい"]', '「畏れる」đọc là「おそれる」(osoreru) — Nghĩa: sợ hãi.', 7, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[畏敬]」trong ngữ cảnh: (tôn kính)', '畏敬', 'いけい', '["かいとうらんま", "いけい", "はしげた", "ちょうじゅ"]', '「畏敬」đọc là「いけい」(ikei) — Nghĩa: tôn kính.', 8, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[畏縮する]」trong ngữ cảnh: (hạ mình)', '畏縮する', 'いしゅくする', '["いしゅくする", "しんぼくをふかめる", "しもん", "じゅうおうむじん"]', '「畏縮する」đọc là「いしゅくする」(ishukusuru) — Nghĩa: hạ mình.', 9, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[寿命]」trong ngữ cảnh: (tuổi thọ)', '寿命', 'じゅみょう', '["がんたん", "はばつ", "にょじつ", "じゅみょう"]', '「寿命」đọc là「じゅみょう」(jumyou) — Nghĩa: tuổi thọ.', 10, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[平均寿命]」trong ngữ cảnh: (tuổi thọ trung bình)', '平均寿命', 'へいきんじゅみょう', '["へんせん", "こうてつする", "へいきんじゅみょう", "でんこうせっか"]', '「平均寿命」đọc là「へいきんじゅみょう」(heikinjumyou) — Nghĩa: tuổi thọ trung bình.', 11, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[長寿]」trong ngữ cảnh: (trường thọ)', '長寿', 'ちょうじゅ', '["とうたする", "ちょうじゅ", "すうようなさんぎょう", "けんやくいえ"]', '「長寿」đọc là「ちょうじゅ」(chouju) — Nghĩa: trường thọ.', 12, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[恭しい]」trong ngữ cảnh: (cung kính)', '恭しい', 'うやうやしい', '["うやうやしい", "とうたする", "しへい", "もうでる"]', '「恭しい」đọc là「うやうやしい」(uyauyashii) — Nghĩa: cung kính.', 13, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[恭順]」trong ngữ cảnh: (trung thành)', '恭順', 'きょうじゅん', '["にかしょ", "せんてひっしょう", "いかんにたえない", "きょうじゅん"]', '「恭順」đọc là「きょうじゅん」(kyoujun) — Nghĩa: trung thành.', 14, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[恭賀新年]」trong ngữ cảnh: (chức mừng năm mới)', '恭賀新年', 'きょうがしんねん', '["けんそんする", "ぞうへいきょく", "きょうがしんねん", "じょさいがない"]', '「恭賀新年」đọc là「きょうがしんねん」(kyougashinnen) — Nghĩa: chức mừng năm mới.', 15, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TỐN]」(khiêm tốn, không kém hơn) — Mẹo nhớ: Dạy con cháu đi lại khiêm TỐN?', 'TỐN', '遜', '["汰", "畏", "寿", "遜"]', 'Chữ「遜」(TỐN) — khiêm tốn, không kém hơn. Từ tiêu biểu: 謙遜する（けんそんする）.', 16, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[THẢI]」(loại bỏ, đào thải tự nhiên) — Mẹo nhớ: Em Thuỷ Béo quá bị đào THẢI?', 'THẢI', '汰', '["恭", "慶", "汰", "寿"]', 'Chữ「汰」(THẢI) — loại bỏ, đào thải tự nhiên. Từ tiêu biểu: 淘汰する（とうたする）.', 17, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[ÚY]」(sợ hãi, tôn kính) — Mẹo nhớ: đại ÚY ra đồng (ĐIỀN) thì thấy bộ y (衣) phục mất đầu nên sợ hãi?', 'ÚY', '畏', '["旦", "畏", "慶", "弔"]', 'Chữ「畏」(ÚY) — sợ hãi, tôn kính. Từ tiêu biểu: 畏れる（おそれる）.', 18, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[THỌ]」(thiếp cưới, tuổi thọ) — Mẹo nhớ: Trải qua 3 lần thốn thì sẽ sống THỌ?', 'THỌ', '寿', '["寿", "旦", "詣", "訃"]', 'Chữ「寿」(THỌ) — thiếp cưới, tuổi thọ. Từ tiêu biểu: 寿（ひさし）.', 19, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[CUNG]」(cung kính, trung thành) — Mẹo nhớ: CUNG bằng cả con TIM là CUNG kính?', 'CUNG', '恭', '["訃", "喪", "累", "恭"]', 'Chữ「恭」(CUNG) — cung kính, trung thành. Từ tiêu biểu: 恭しい（うやうやしい）.', 20, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[KHÁNH]」(việc hỉ, chúc mừng) — Mẹo nhớ: 国慶: こっけい quốc KHÁNH?', 'KHÁNH', '慶', '["幣", "俸", "慶", "累"]', 'Chữ「慶」(KHÁNH) — việc hỉ, chúc mừng. Từ tiêu biểu: 慶事（けいじ）.', 21, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[ĐIẾU]」(chia buồn, điếu văn) — Mẹo nhớ: Đệ bỏ sừng thành ĐIẾU?', 'ĐIẾU', '弔', '["倹", "弔", "俸", "酬"]', 'Chữ「弔」(ĐIẾU) — chia buồn, điếu văn. Từ tiêu biểu: 弔う（とむらう）.', 22, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[ĐÁN]」(ngày đầu năm mới, tạm dừng) — Mẹo nhớ: Ngày mùng 1 tết nguyên ĐÁN?', 'ĐÁN', '旦', '["旦", "倹", "廉", "租"]', 'Chữ「旦」(ĐÁN) — ngày đầu năm mới, tạm dừng. Từ tiêu biểu: 元旦（がんたん）.', 23, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[NGHỆ]」(đi hành hương, đi lễ chùa ngày đầu năm) — Mẹo nhớ: chỉ tay 旨 nói 言cho kẻ hành hương biết kia là NGHỆ an?', 'NGHỆ', '詣', '["租", "配", "賦", "詣"]', 'Chữ「詣」(NGHỆ) — đi hành hương, đi lễ chùa ngày đầu năm. Từ tiêu biểu: 詣でる（もうでる）.', 24, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[PHÓ]」(tin buồn/ cáo phó của người bạn cũ) — Mẹo nhớ: Về chuyện cáo PHÓ (訃) , thì không nên NÓI (言) TO(卜)?', 'PHÓ', '訃', '["逸", "赴", "訃", "賦"]', 'Chữ「訃」(PHÓ) — tin buồn/ cáo phó của người bạn cũ. Từ tiêu biểu: 旧友の訃報（きゅうゆうのふほう）.', 25, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 13;
    IF v_ch_id IS NOT NULL THEN
        DELETE FROM kanji_exercises WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[括弧でくくる]」trong ngữ cảnh: (đóng ngoặc)', '括弧でくくる', 'かっこでくくる', '["かっこでくくる", "すいちょく", "ようせい", "たくみのわざ"]', '「括弧でくくる」đọc là「かっこでくくる」(kakkodekukuru) — Nghĩa: đóng ngoặc.', 1, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[凹レンズ]」trong ngữ cảnh: (thấu kính lõm)', '凹レンズ', 'おうレンズれんず', '["せんい", "かもん", "ぶんきする", "おうレンズれんず"]', '「凹レンズ」đọc là「おうレンズれんず」(ourenzurenzu) — Nghĩa: thấu kính lõm.', 2, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[凸レンズ]」trong ngữ cảnh: (thấu kính lồi)', '凸レンズ', 'とつレンズれんず', '["いっしんいったい", "にじがかかる", "とつレンズれんず", "かいしょ‐ぎょうしょ‐そうしょ"]', '「凸レンズ」đọc là「とつレンズれんず」(totsurenzurenzu) — Nghĩa: thấu kính lồi.', 3, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[凹凸がある]」trong ngữ cảnh: (có sự lồi lõm)', '凹凸がある', 'おうとつがある', '["わこうどうじん", "おうとつがある", "きせいのじじつ", "ゆいがどくそん"]', '「凹凸がある」đọc là「おうとつがある」(outotsugaaru) — Nghĩa: có sự lồi lõm.', 4, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[凸凹した道]」trong ngữ cảnh: (con dường lồi lõm không bằng phẳng)', '凸凹した道', 'でこぼこしたみち', '["でこぼこしたみち", "めいど（めいど）", "せんす", "せんぺんばんか"]', '「凸凹した道」đọc là「でこぼこしたみち」(dekobokoshitamichi) — Nghĩa: con dường lồi lõm không bằng phẳng.', 5, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[よだれが垂れる]」trong ngữ cảnh: (chảy nước dãi)', 'よだれが垂れる', 'よだれがたれる', '["はしをかける", "ごふくうりば", "むねをつたえる", "よだれがたれる"]', '「よだれが垂れる」đọc là「よだれがたれる」(yodaregatareru) — Nghĩa: chảy nước dãi.', 6, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[垂らす]」trong ngữ cảnh: (treo lủng lẳng)', '垂らす', 'たらす', '["でこぼこしたみち", "いっすんさきはやみ", "たらす", "はいかい"]', '「垂らす」đọc là「たらす」(tarasu) — Nghĩa: treo lủng lẳng.', 7, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[雨垂れ]」trong ngữ cảnh: (giọt mưa rơi)', '雨垂れ', 'あまだれ', '["じゅきょう", "あまだれ", "むがむちゅう", "こどものいたずら"]', '「雨垂れ」đọc là「あまだれ」(amadare) — Nghĩa: giọt mưa rơi.', 8, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[垂直]」trong ngữ cảnh: (thẳng đứng)', '垂直', 'すいちょく', '["すいちょく", "ふきん", "おんいん", "ごまあぶら"]', '「垂直」đọc là「すいちょく」(suichoku) — Nghĩa: thẳng đứng.', 9, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[雪の塊]」trong ngữ cảnh: (đống tuyết)', '雪の塊', 'ゆきのかたまり', '["ごまあぶら", "ぼうせき", "ばっぽんそくげん", "ゆきのかたまり"]', '「雪の塊」đọc là「ゆきのかたまり」(yukinokatamari) — Nghĩa: đống tuyết.', 10, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[牛肉を塊で買う]」trong ngữ cảnh: (mua 1 miếng thịt)', '牛肉を塊で買う', 'ぎゅうにくをかたまりでかう', '["きゅうてんちょっか", "しめんそか", "ぎゅうにくをかたまりでかう", "おうレンズれんず"]', '「牛肉を塊で買う」đọc là「ぎゅうにくをかたまりでかう」(gyuunikuokatamaridekau) — Nghĩa: mua 1 miếng thịt.', 11, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[金塊]」trong ngữ cảnh: (vàng khối, thỏi vàng)', '金塊', 'きんかい', '["しょうぎをさす", "きんかい", "かぶき", "しっぱいを取りつくろう"]', '「金塊」đọc là「きんかい」(kinkai) — Nghĩa: vàng khối, thỏi vàng.', 12, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[経路]」trong ngữ cảnh: (đường đi)', '経路', 'けいろ', '["けいろ", "ふくをぬう", "おうぎであおぐ", "ちょっけい"]', '「経路」đọc là「けいろ」(keiro) — Nghĩa: đường đi.', 13, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[直径]」trong ngữ cảnh: (đường kính)', '直径', 'ちょっけい', '["れいえん", "じゅがく", "じょじし", "ちょっけい"]', '「直径」đọc là「ちょっけい」(chokkei) — Nghĩa: đường kính.', 14, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[半径]」trong ngữ cảnh: (bán kính)', '半径', 'はんけい', '["めいそう", "ただし", "はんけい", "じょじし"]', '「半径」đọc là「はんけい」(hankei) — Nghĩa: bán kính.', 15, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[HỒ]」(đóng ngoặc, hình cung) — Mẹo nhớ: bắn cung (弓) qua (瓜) HỒ?', 'HỒ', '弧', '["凹", "凸", "垂", "弧"]', 'Chữ「弧」(HỒ) — đóng ngoặc, hình cung. Từ tiêu biểu: 括弧でくくる（かっこでくくる）.', 16, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[AO]」(thấu kính lõm) — Mẹo nhớ: Cái AO có chỗ lõm ở giữa hình chữ U?', 'AO', '凹', '["塊", "経", "凹", "垂"]', 'Chữ「凹」(AO) — thấu kính lõm. Từ tiêu biểu: 凹レンズ（おうレンズれんず）.', 17, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[ĐỘT]」(thấu kính lồi, có sự lồi lõm) — Mẹo nhớ: hình chữ nhật ĐỘT ngột lồi lên?', 'ĐỘT', '凸', '["又", "凸", "経", "岐"]', 'Chữ「凸」(ĐỘT) — thấu kính lồi, có sự lồi lõm. Từ tiêu biểu: 凸レンズ（とつレンズれんず）.', 18, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[THÙY]」(chảy nước dãi, treo lủng lẳng) — Mẹo nhớ: THÙY làm tường rào bằng 5 thanh ngang 3 thanh dọc?', 'THÙY', '垂', '["垂", "又", "既", "且"]', 'Chữ「垂」(THÙY) — chảy nước dãi, treo lủng lẳng. Từ tiêu biểu: よだれが垂れる（よだれがたれる）.', 19, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[KHỐI]」(đống tuyết, mua 1 miếng thịt) — Mẹo nhớ: Con quỷ 鬼 từ đất 土 chui ra biến thành KHỐI đá 塊?', 'KHỐI', '塊', '["且", "但", "謡", "塊"]', 'Chữ「塊」(KHỐI) — đống tuyết, mua 1 miếng thịt. Từ tiêu biểu: 雪の塊（ゆきのかたまり）.', 20, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[KINH]」(đường đi, đường kính) — Mẹo nhớ: Sợi chỉ (糸) rơi đi rơi lại (又) xuống đất (土)nhìn KINH quá?', 'KINH', '経', '["唄", "吟", "経", "謡"]', 'Chữ「経」(KINH) — đường đi, đường kính. Từ tiêu biểu: 経路（けいろ）.', 21, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[KÌ]」(phân nhánh, nội dung trải rộng) — Mẹo nhớ: phân công cho Chi (支) nhánh trên Núi (山) theo định KÌ?', 'KÌ', '岐', '["叙", "岐", "吟", "詠"]', 'Chữ「岐」(KÌ) — phân nhánh, nội dung trải rộng. Từ tiêu biểu: 分岐する（ぶんきする）.', 22, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[HỰU]」(hãy nắm lấy cơ hội sau, việc cho thuê lại sách) — Mẹo nhớ: HỰU vắt chéo 2 tay trước ngực?', 'HỰU', '又', '["又", "叙", "随", "韻"]', 'Chữ「又」(HỰU) — hãy nắm lấy cơ hội sau, việc cho thuê lại sách. Từ tiêu biểu: 又の機会にしましょう（またのきかいにしましょう）.', 23, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[KÍ]」(tình trạng đã quá muộn, đã kết hôn) — Mẹo nhớ: Lấn cấn (艮) thì cũng đã KÍ (旡) rồi?', 'KÍ', '既', '["韻", "諧", "碁", "既"]', 'Chữ「既」(KÍ) — tình trạng đã quá muộn, đã kết hôn. Từ tiêu biểu: 既に手遅れの状態（すでにておくれのじょうたい）.', 24, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[THẢ]」(ngoài ra) — Mẹo nhớ: THẢ nguyệt (月) ra  cưỡi trên nhất (一)?', 'THẢ', '且', '["棋", "駒", "且", "碁"]', 'Chữ「且」(THẢ) — ngoài ra. Từ tiêu biểu: 且つ（かつ）.', 25, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 14;
    IF v_ch_id IS NOT NULL THEN
        DELETE FROM kanji_exercises WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[一寸]」trong ngữ cảnh: (1 sun (3,03cm) đơn vị đo của nhật)', '一寸', 'いっすん', '["いっすん", "しゃくどをはかる", "だんがいする", "ぎしんあんき"]', '「一寸」đọc là「いっすん」(issun) — Nghĩa: 1 sun (3,03cm) đơn vị đo của nhật.', 1, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[寸法を測る]」trong ngữ cảnh: (đo kích thước)', '寸法を測る', 'すんぽうをはかる', '["かいぞくばんCD", "しっき", "おんしんびょうどう", "すんぽうをはかる"]', '「寸法を測る」đọc là「すんぽうをはかる」(sunpouohakaru) — Nghĩa: đo kích thước.', 2, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[寸前]」trong ngữ cảnh: (ngay trước khi...)', '寸前', 'すんぜん', '["せっしやくわん", "ほりょしゅうようじょ", "すんぜん", "みっかかんのゆうよをあたえる"]', '「寸前」đọc là「すんぜん」(sunzen) — Nghĩa: ngay trước khi....', 3, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[巻尺]」trong ngữ cảnh: (thước dây)', '巻尺', 'まきじゃく', '["ながそで", "まきじゃく", "むじゃきなひと", "はしゃ"]', '「巻尺」đọc là「まきじゃく」(makijaku) — Nghĩa: thước dây.', 4, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[尺度を測る]」trong ngữ cảnh: (đo độ dài)', '尺度を測る', 'しゃくどをはかる', '["しゃくどをはかる", "あいぞめ", "むほん", "からだのしんまでひえる"]', '「尺度を測る」đọc là「しゃくどをはかる」(shakudoohakaru) — Nghĩa: đo độ dài.', 5, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[縮尺する]」trong ngữ cảnh: (thu nhỏ)', '縮尺する', 'しゅくしゃくする', '["からだのしんまでひえる", "いやなやつ", "ざんぎゃくなこうい", "しゅくしゃくする"]', '「縮尺する」đọc là「しゅくしゃくする」(shukushakusuru) — Nghĩa: thu nhỏ.', 6, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[藤の花]」trong ngữ cảnh: (hoa tử đằng)', '藤の花', 'ふじのはな', '["かけごと", "トランプにたいきんをかける", "ふじのはな", "じゃまする"]', '「藤の花」đọc là「ふじのはな」(fujinohana) — Nghĩa: hoa tử đằng.', 7, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[藤色]」trong ngữ cảnh: (màu tím)', '藤色', 'ふじいろ', '["ぎゃくさつ", "ふじいろ", "すんぜん", "くつをはく"]', '「藤色」đọc là「ふじいろ」(fujiiro) — Nghĩa: màu tím.', 8, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[藍色]」trong ngữ cảnh: (màu xanh lam)', '藍色', 'あいいろ', '["あいいろ", "きどあいらく", "だんちょうのおもい", "かんがいむりょう"]', '「藍色」đọc là「あいいろ」(aiiro) — Nghĩa: màu xanh lam.', 9, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[藍染め]」trong ngữ cảnh: (nhuộm màu lam)', '藍染め', 'あいぞめ', '["せっとうはんをけんきょする", "とうのじだい", "りれきしょ", "あいぞめ"]', '「藍染め」đọc là「あいぞめ」(aizome) — Nghĩa: nhuộm màu lam.', 10, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[漆を塗る]」trong ngữ cảnh: (quét sơn)', '漆を塗る', 'うるしをぬる', '["むぼうなけいかく", "かっしょくのはだ", "うるしをぬる", "りれきしょ"]', '「漆を塗る」đọc là「うるしをぬる」(urushionuru) — Nghĩa: quét sơn.', 11, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[漆器]」trong ngữ cảnh: (đồ gỗ, sơn mài)', '漆器', 'しっき', '["すんぽうをはかる", "しっき", "しっそうしゃ", "だめ"]', '「漆器」đọc là「しっき」(shikki) — Nghĩa: đồ gỗ, sơn mài.', 12, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[漆黒の髪]」trong ngữ cảnh: (mái tóc đen nhánh)', '漆黒の髪', 'しっこくのかみ', '["しっこくのかみ", "すんぽうをはかる", "ばいしんせいど", "こいのとりこになる"]', '「漆黒の髪」đọc là「しっこくのかみ」(shikkokunokami) — Nghĩa: mái tóc đen nhánh.', 13, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[褐色の肌]」trong ngữ cảnh: (làn da nâu)', '褐色の肌', 'かっしょくのはだ', '["じゅんきょうしゃ", "せいかつひをまかなう", "ぞうわい", "かっしょくのはだ"]', '「褐色の肌」đọc là「かっしょくのはだ」(kasshokunohada) — Nghĩa: làn da nâu.', 14, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[茶褐色の髪]」trong ngữ cảnh: (mái tóc nâu trà)', '茶褐色の髪', 'ちゃかっしょくのかみ', '["れいこくなひと", "けいやくをりこうする", "ちゃかっしょくのかみ", "ぞうわい"]', '「茶褐色の髪」đọc là「ちゃかっしょくのかみ」(chakasshokunokami) — Nghĩa: mái tóc nâu trà.', 15, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[THỐN]」(1 sun (3, đo kích thước) — Mẹo nhớ: THỐN quá lấy Đơn vị đo Mười chấm chủ?', 'THỐN', '寸', '["尺", "藤", "藍", "寸"]', 'Chữ「寸」(THỐN) — 1 sun (3, đo kích thước. Từ tiêu biểu: 一寸（いっすん）.', 16, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[XÍCH]」(thước dây, đo độ dài) — Mẹo nhớ: cái XÍCH dùng để xích Con cương Thi (尸) dài cả THƯỚC (尺)?', 'XÍCH', '尺', '["漆", "褐", "尺", "藍"]', 'Chữ「尺」(XÍCH) — thước dây, đo độ dài. Từ tiêu biểu: 巻尺（まきじゃく）.', 17, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[ĐẰNG]」(hoa tử đằng, màu tím) — Mẹo nhớ: bụi hoa tử ĐẰNG chỉ mọc vào t2(月), t4(水) ko phải thứ 3(火)?', 'ĐẰNG', '藤', '["錦", "藤", "褐", "丹"]', 'Chữ「藤」(ĐẰNG) — hoa tử đằng, màu tím. Từ tiêu biểu: 藤の花（ふじのはな）.', 18, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[LAM]」(màu xanh lam, nhuộm màu lam) — Mẹo nhớ: Cỏ(艹) mà bị Giam (監) hãm trong phòng kín lâu ngày sẽ bị đổi mầu          thành mầu LAM?', 'LAM', '藍', '["藍", "錦", "鈴", "唐"]', 'Chữ「藍」(LAM) — màu xanh lam, nhuộm màu lam. Từ tiêu biểu: 藍色（あいいろ）.', 19, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TẤT]」(quét sơn, đồ gỗ) — Mẹo nhớ: Thuỷ ( 氵) đội Mũ đi TẤT cầm cây Sơn nước?', 'TẤT', '漆', '["唐", "袖", "裾", "漆"]', 'Chữ「漆」(TẤT) — quét sơn, đồ gỗ. Từ tiêu biểu: 漆を塗る（うるしをぬる）.', 20, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[HẠT]」(làn da nâu, mái tóc nâu trà) — Mẹo nhớ: Áo (衤) anh HẠT (曷  ) bẩn đổi màu nâu ám mùi ( 匂) suốt ngày (日)?', 'HẠT', '褐', '["襟", "芯", "褐", "裾"]', 'Chữ「褐」(HẠT) — làn da nâu, mái tóc nâu trà. Từ tiêu biểu: 褐色の肌（かっしょくのはだ）.', 21, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[ĐAN]」(tìm hiểu 1 cách tỉ mỉ, hết sức) — Mẹo nhớ: Quynh (冂) tỉ mỉ ĐAN áo cho chủ (丶)?', 'ĐAN', '丹', '["駄", "丹", "芯", "履"]', 'Chữ「丹」(ĐAN) — tìm hiểu 1 cách tỉ mỉ, hết sức. Từ tiêu biểu: 丹念に調べる（たんねんにしらべる）.', 22, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[CẨM]」(kimono bằng thổ cẩm, mang vinh quang về quê hương) — Mẹo nhớ: khăn(巾) Thổ CẨM  có kim (金) tuyến màu trắng(白)?', 'CẨM', '錦', '["錦", "駄", "紐", "縛"]', 'Chữ「錦」(CẨM) — kimono bằng thổ cẩm, mang vinh quang về quê hương. Từ tiêu biểu: 錦の着物（にしきのきもの）.', 23, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[LINH]」(chuông cửa, chuông gió) — Mẹo nhớ: LINH ra lệnh(令)  làm cái chuông bằng kim loại(金)?', 'LINH', '鈴', '["縛", "賄", "賂", "鈴"]', 'Chữ「鈴」(LINH) — chuông cửa, chuông gió. Từ tiêu biểu: ドアの呼び鈴（ドアのよびりん）.', 24, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[ĐƯỜNG]」(thời đại nhà đường, phát ngôn bất ngờ) — Mẹo nhớ: Miệng (口) (em) trong nhà  (广) nói ra ngoài ĐƯỜNG?', 'ĐƯỜNG', '唐', '["痴", "窃", "唐", "賂"]', 'Chữ「唐」(ĐƯỜNG) — thời đại nhà đường, phát ngôn bất ngờ. Từ tiêu biểu: 唐の時代（とうのじだい）.', 25, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 15;
    IF v_ch_id IS NOT NULL THEN
        DELETE FROM kanji_exercises WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[奴隷]」trong ngữ cảnh: (nô lệ)', '奴隷', 'どれい', '["どれい", "ぶつぎをかもす", "かばんをかかえる", "かいがら"]', '「奴隷」đọc là「どれい」(dorei) — Nghĩa: nô lệ.', 1, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[大国に隷属する]」trong ngữ cảnh: (lệ thuộc vào nước lớn)', '大国に隷属する', 'たいこくにれいぞくする', '["しゅぶそくとう", "たまごのから", "ちゅうとんち", "たいこくにれいぞくする"]', '「大国に隷属する」đọc là「たいこくにれいぞくする」(taikokunireizokusuru) — Nghĩa: lệ thuộc vào nước lớn.', 2, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[死刑囚]」trong ngữ cảnh: (tội phạm tử hình)', '死刑囚', 'しけいしゅう', '["こうそ", "しょうじのさん", "しけいしゅう", "こめだわら"]', '「死刑囚」đọc là「しけいしゅう」(shikeishuu) — Nghĩa: tội phạm tử hình.', 3, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[囚人]」trong ngữ cảnh: (tù nhân)', '囚人', 'しゅうじん', '["ロッカーをせじょうする", "しゅうじん", "おわん", "かぎをつくる"]', '「囚人」đọc là「しゅうじん」(shuujin) — Nghĩa: tù nhân.', 4, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[軍隊が駐屯する]」trong ngữ cảnh: (quân đội đồn trú)', '軍隊が駐屯する', 'ぐんたいがちゅうとんする', '["ぐんたいがちゅうとんする", "さんばしにふねがつく", "ふろしき", "じょうをおろす"]', '「軍隊が駐屯する」đọc là「ぐんたいがちゅうとんする」(guntaigachuutonsuru) — Nghĩa: quân đội đồn trú.', 5, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[駐屯地]」trong ngữ cảnh: (nơi đồn trú)', '駐屯地', 'ちゅうとんち', '["さけをいっしょうのむ", "かぜかおるごがつ", "かいとうらんま", "ちゅうとんち"]', '「駐屯地」đọc là「ちゅうとんち」(chuutonchi) — Nghĩa: nơi đồn trú.', 6, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[障子の桟]」trong ngữ cảnh: (khung cửa)', '障子の桟', 'しょうじのさん', '["ふせん", "かまでこめをたく", "しょうじのさん", "きゅうりょう"]', '「障子の桟」đọc là「しょうじのさん」(shoujinosan) — Nghĩa: khung cửa.', 7, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[桟橋に船が着く]」trong ngữ cảnh: (con tàu cập bến)', '桟橋に船が着く', 'さんばしにふねがつく', '["わりばし", "さんばしにふねがつく", "じゅうおうむじん", "くるまいす"]', '「桟橋に船が着く」đọc là「さんばしにふねがつく」(sanbashinifunegatsuku) — Nghĩa: con tàu cập bến.', 8, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[花壇]」trong ngữ cảnh: (bồn hoa)', '花壇', 'かだん', '["かだん", "わりばし", "でんこうせっか", "きんせんかんかく"]', '「花壇」đọc là「かだん」(kadan) — Nghĩa: bồn hoa.', 9, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[壇に上がる]」trong ngữ cảnh: (bước lên bục)', '壇に上がる', 'だんにあがる', '["からにとじこもる", "しけいしゅう", "はっこうしょくひん", "だんにあがる"]', '「壇に上がる」đọc là「だんにあがる」(danniagaru) — Nghĩa: bước lên bục.', 10, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[教壇]」trong ngữ cảnh: (bục giảng)', '教壇', 'きょうだん', '["せんてひっしょう", "べいいちたわら", "きょうだん", "しょくぜん"]', '「教壇」đọc là「きょうだん」(kyoudan) — Nghĩa: bục giảng.', 11, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[土壇場で逆転する]」trong ngữ cảnh: (xoay chuyển tình thế vào phút cuối)', '土壇場で逆転する', 'どたんばでぎゃくてんする', '["めんるい", "どたんばでぎゃくてんする", "せっちゅうあんをだす", "ますせき"]', '「土壇場で逆転する」đọc là「どたんばでぎゃくてんする」(dotanbadegyakutensuru) — Nghĩa: xoay chuyển tình thế vào phút cuối.', 12, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[塀を立てる]」trong ngữ cảnh: (xây tường bao quanh)', '塀を立てる', 'へいをたてる', '["へいをたてる", "せんべい", "とりにくをくしにさす", "せいとんする"]', '「塀を立てる」đọc là「へいをたてる」(heiotateru) — Nghĩa: xây tường bao quanh.', 13, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[板塀]」trong ngữ cảnh: (hàng rào)', '板塀', 'いたべい', '["ひとつぼ", "やねのかわら", "かんげきをぬう", "いたべい"]', '「板塀」đọc là「いたべい」(itabei) — Nghĩa: hàng rào.', 14, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[一坪]」trong ngữ cảnh: (1 stubo= 3,31m2 (ơn vị đo của nhật))', '一坪', 'ひとつぼ', '["ふきゅうのめいさく", "いちきん", "ひとつぼ", "ちゃわんとおわん"]', '「一坪」đọc là「ひとつぼ」(hitotsubo) — Nghĩa: 1 stubo= 3,31m2 (ơn vị đo của nhật).', 15, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[LỆ]」(nô lệ, lệ thuộc vào nước lớn) — Mẹo nhớ: kẻ vô liêm Sỉ (士) bị kì thị(示) và ngược Đãi (隶) như nô LỆ?', 'LỆ', '隷', '["囚", "屯", "桟", "隷"]', 'Chữ「隷」(LỆ) — nô lệ, lệ thuộc vào nước lớn. Từ tiêu biểu: 奴隷（どれい）.', 16, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TÙ]」(tội phạm tử hình, tù nhân) — Mẹo nhớ: Người (人) bị giam trong 4 bức tường (囗) là TÙ nhân?', 'TÙ', '囚', '["壇", "塀", "囚", "桟"]', 'Chữ「囚」(TÙ) — tội phạm tử hình, tù nhân. Từ tiêu biểu: 死刑囚（しけいしゅう）.', 17, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TRUÂN]」(quân đội đồn trú, nơi đồn trú) — Mẹo nhớ: đường (丿) đi qua 7 (七)  núi rất gian TRUÂN?', 'TRUÂN', '屯', '["陵", "屯", "塀", "坪"]', 'Chữ「屯」(TRUÂN) — quân đội đồn trú, nơi đồn trú. Từ tiêu biểu: 軍隊が駐屯する（ぐんたいがちゅうとんする）.', 18, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[SẠN]」(khung cửa, con tàu cập bến) — Mẹo nhớ: Cây (木)  Qua  (戈)  2 (二)  lần chai SẠN?', 'SẠN', '桟', '["桟", "陵", "郭", "楼"]', 'Chữ「桟」(SẠN) — khung cửa, con tàu cập bến. Từ tiêu biểu: 障子の桟（しょうじのさん）.', 19, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[ĐÀN]」(bồn hoa, bước lên bục) — Mẹo nhớ: Chỗ đất ( 土) bằng đội mũ lập ĐÀN luân hồi (回) 1 (ー) ngày (日)?', 'ĐÀN', '壇', '["楼", "朽", "舗", "壇"]', 'Chữ「壇」(ĐÀN) — bồn hoa, bước lên bục. Từ tiêu biểu: 花壇（かだん）.', 20, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[BIÊN]」(xây tường bao quanh, hàng rào) — Mẹo nhớ: BIÊN giới hòa Bình (屏) chia đôi vùng Đất( 土)?', 'BIÊN', '塀', '["隙", "柵", "塀", "舗"]', 'Chữ「塀」(BIÊN) — xây tường bao quanh, hàng rào. Từ tiêu biểu: 塀を立てる（へいをたてる）.', 21, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[BÌNH]」(1 stubo= 3, giá đất tính theo đơn vị stubo) — Mẹo nhớ: chỗ đất (土) bằng phẳng ( 平) thì mới có hoà BÌNH (坪)?', 'BÌNH', '坪', '["硝", "坪", "柵", "瓦"]', 'Chữ「坪」(BÌNH) — 1 stubo= 3, giá đất tính theo đơn vị stubo. Từ tiêu biểu: 一坪（ひとつぼ）.', 22, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[LĂNG]」(lăng mộ, thở cúng tại lăng mộ) — Mẹo nhớ: LĂNG tẩm của các Bố (阝) bị Truy (夂) xét đầu Tiên(先)?', 'LĂNG', '陵', '["陵", "硝", "箸", "椀"]', 'Chữ「陵」(LĂNG) — lăng mộ, thở cúng tại lăng mộ. Từ tiêu biểu: 陵（みささぎ）.', 23, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[QUÁCH]」(bao quanh tòa thành, vẽ nét phác thảo) — Mẹo nhớ: Đầu tiên,dùng Miệng (口) dạy Trẻ (子) dựng Bờ đất (阝) làm Thành QUÁCH?', 'QUÁCH', '郭', '["椀", "串", "椅", "郭"]', 'Chữ「郭」(QUÁCH) — bao quanh tòa thành, vẽ nét phác thảo. Từ tiêu biểu: 城郭を巡らす（じょうかくをめぐらす）.', 24, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[LÂU]」(lầu các, nhà trọc trời) — Mẹo nhớ: Cây (木) Gạo (米) mà người Con Gái (女) đã trồng. Được cất giữ ở LÂU 楼 đài...?', 'LÂU', '楼', '["鞄", "籠", "楼", "椅"]', 'Chữ「楼」(LÂU) — lầu các, nhà trọc trời. Từ tiêu biểu: 楼閣（ろうかく）.', 25, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 16;
    IF v_ch_id IS NOT NULL THEN
        DELETE FROM kanji_exercises WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[水槽]」trong ngữ cảnh: (bể cá)', '水槽', 'すいそう', '["すいそう", "はろうちゅういほう", "こんなんをきわめる", "はくだつされる"]', '「水槽」đọc là「すいそう」(suisou) — Nghĩa: bể cá.', 1, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[浴槽]」trong ngữ cảnh: (bồn tắm)', '浴槽', 'よくそう', '["ばせいをあびせる", "きってをはる", "おんねんをはらす", "よくそう"]', '「浴槽」đọc là「よくそう」(yokusou) — Nghĩa: bồn tắm.', 2, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[食糧]」trong ngữ cảnh: (lương thực)', '食糧', 'しょくりょう', '["いっしんいったい", "せんずるところ、せきにんはじぶんにある", "しょくりょう", "あまもり"]', '「食糧」đọc là「しょくりょう」(shokuryou) — Nghĩa: lương thực.', 3, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[食料不足]」trong ngữ cảnh: (thiếu lương thực)', '食料不足', 'しょくりょうぶそく', '["かたわら", "しょくりょうぶそく", "ぜんれいにならう", "そうごうかんぼうやく"]', '「食料不足」đọc là「しょくりょうぶそく」(shokuryoubusoku) — Nghĩa: thiếu lương thực.', 4, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[窯業]」trong ngữ cảnh: (ngành công nghiệp làm gốm)', '窯業', 'ようぎょう', '["ようぎょう", "におい", "きのかわをはぐ", "ゆいがどくそん"]', '「窯業」đọc là「ようぎょう」(yougyou) — Nghĩa: ngành công nghiệp làm gốm.', 5, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[切手を貼る]」trong ngữ cảnh: (dán tem)', '切手を貼る', 'きってをはる', '["せんぺんばんか", "ろうにんする", "さくしゃのねらい", "きってをはる"]', '「切手を貼る」đọc là「きってをはる」(kitteoharu) — Nghĩa: dán tem.', 6, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[添付する]」trong ngữ cảnh: (đính kèm)', '添付する', 'てんぷする', '["ガスがすがもれる", "しょくりょう", "てんぷする", "さくしゃのねらい"]', '「添付する」đọc là「てんぷする」(tenpusuru) — Nghĩa: đính kèm.', 7, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[爪がはがれる]」trong ngữ cảnh: (móng tay bị bong)', '爪がはがれる', 'つめがはがれる', '["むがむちゅう", "つめがはがれる", "さげすむようなめつき", "りんじきゅうぎょう"]', '「爪がはがれる」đọc là「つめがはがれる」(tsumegahagareru) — Nghĩa: móng tay bị bong.', 8, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[ペンキが剝げる]」trong ngữ cảnh: (sơn bị phai màu)', 'ペンキが剝げる', 'ペンキがはげる', '["ペンキがはげる", "つめがはがれる", "しょっけんをらんようする", "わがこをできあいする"]', '「ペンキが剝げる」đọc là「ペンキがはげる」(penkigahageru) — Nghĩa: sơn bị phai màu.', 9, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[化けの皮が剝がす]」trong ngữ cảnh: (lột mặt nạ)', '化けの皮が剝がす', 'ばけのかわがはがす', '["ばっぽんそくげん", "えんこん", "しょせんかなわぬゆめ", "ばけのかわがはがす"]', '「化けの皮が剝がす」đọc là「ばけのかわがはがす」(bakenokawagahagasu) — Nghĩa: lột mặt nạ.', 10, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[木の皮を剝ぐ]」trong ngữ cảnh: (bóc vỏ cây)', '木の皮を剝ぐ', 'きのかわをはぐ', '["きゅうてんちょっか", "しめんそか", "きのかわをはぐ", "バラのはながにおう"]', '「木の皮を剝ぐ」đọc là「きのかわをはぐ」(kinokawaohagu) — Nghĩa: bóc vỏ cây.', 11, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[剝製]」trong ngữ cảnh: (mẫu vật)', '剝製', 'はくせい', '["れきしをさかのぼる", "はくせい", "しめんそか", "こどもをほうようする"]', '「剝製」đọc là「はくせい」(hakusei) — Nghĩa: mẫu vật.', 12, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[剝奪される]」trong ngữ cảnh: (bị tước đoạt, bị lấy đi)', '剝奪される', 'はくだつされる', '["はくだつされる", "あきかんをつぶす", "ちゅういをかんきする", "よくそう"]', '「剝奪される」đọc là「はくだつされる」(hakudatsusareru) — Nghĩa: bị tước đoạt, bị lấy đi.', 13, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[首が据わる]」trong ngữ cảnh: (cổ cứng cáp)', '首が据わる', 'くびがすわる', '["よくそう", "ライバルをけおとす", "しょくりょうぶそく", "くびがすわる"]', '「首が据わる」đọc là「くびがすわる」(kubigasuwaru) — Nghĩa: cổ cứng cáp.', 14, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[机を据える]」trong ngữ cảnh: (đặt bàn)', '机を据える', 'つくえをすえる', '["ざゆうのめい", "てんぷする", "つくえをすえる", "ぼうけんしん"]', '「机を据える」đọc là「つくえをすえる」(tsukueosueru) — Nghĩa: đặt bàn.', 15, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TÀO]」(bể cá, bồn tắm) — Mẹo nhớ: Nước TÀO (曹) hay dùng Gỗ (木) làm Bể tắm?', 'TÀO', '槽', '["糧", "窯", "貼", "槽"]', 'Chữ「槽」(TÀO) — bể cá, bồn tắm. Từ tiêu biểu: 水槽（すいそう）.', 16, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[LƯƠNG]」(lương thực, thiếu lương thực) — Mẹo nhớ: LƯƠNG thực tính bằng số lượng ( 量) gạo (米)?', 'LƯƠNG', '糧', '["剝", "据", "糧", "貼"]', 'Chữ「糧」(LƯƠNG) — lương thực, thiếu lương thực. Từ tiêu biểu: 食糧（しょくりょう）.', 17, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[DIÊU]」(lò nung, ngành công nghiệp làm gốm) — Mẹo nhớ: Cho con Dê (羔) vào Lò (穴) nấu DIÊU?', 'DIÊU', '窯', '["蹴", "窯", "据", "斬"]', 'Chữ「窯」(DIÊU) — lò nung, ngành công nghiệp làm gốm. Từ tiêu biểu: 窯（かま）.', 18, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[THIẾP]」(dán tem, đính kèm) — Mẹo nhớ: Chiếm (占) Tiền (貝) của người khác về dán vào mặt thê THIẾP?', 'THIẾP', '貼', '["貼", "蹴", "狙", "冒"]', 'Chữ「貼」(THIẾP) — dán tem, đính kèm. Từ tiêu biểu: 切手を貼る（きってをはる）.', 19, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[BÁC]」(móng tay bị bong, sơn bị phai màu) — Mẹo nhớ: Tôi cùng BÁC lấy dao (刂) gọt quả Cóc?', 'BÁC', '剝', '["冒", "臨", "傍", "剝"]', 'Chữ「剝」(BÁC) — móng tay bị bong, sơn bị phai màu. Từ tiêu biểu: 爪がはがれる（つめがはがれる）.', 20, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[CƯ]」(cổ cứng cáp, đặt bàn) — Mẹo nhớ: Tự tay ( 扌) lắp đặt đồ đạc ở nơi mình CƯ (居) trú?', 'CƯ', '据', '["鎮", "窮", "据", "傍"]', 'Chữ「据」(CƯ) — cổ cứng cáp, đặt bàn. Từ tiêu biểu: 首が据わる（くびがすわる）.', 21, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TRẢM]」(chém đối thủ, phê phán xã hội hiện nay) — Mẹo nhớ: Xe (車) có Dao (斤) là Cẩu đầu TRẢM của bao thanh Thiên?', 'TRẢM', '斬', '["撤", "斬", "窮", "堪"]', 'Chữ「斬」(TRẢM) — chém đối thủ, phê phán xã hội hiện nay. Từ tiêu biểu: 相手を斬る（あいてをきる）.', 22, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[XÚC]」(đá bóng, đánh bại đối thủ) — Mẹo nhớ: Túc lấy Chân (足 ) XÚC bóng cho Tựu (就)?', 'XÚC', '蹴', '["蹴", "撤", "喚", "享"]', 'Chữ「蹴」(XÚC) — đá bóng, đánh bại đối thủ. Từ tiêu biểu: ボールを蹴る（ボールをける）.', 23, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[THƯ]」(nhắm vào con mồi, bây giờ là cơ hội đó) — Mẹo nhớ: Thả (且) chó (犭) đi dạo rất THƯ  thái nhưng MỤC TIÊU là đi ngắm gái?', 'THƯ', '狙', '["享", "嗅", "匂", "狙"]', 'Chữ「狙」(THƯ) — nhắm vào con mồi, bây giờ là cơ hội đó. Từ tiêu biểu: 獲物を狙う（えものをねらう）.', 24, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[MẠO]」(đương đầu với nguy hiểm, chống chọi với bệnh tật) — Mẹo nhớ: Mắt (目) nhìn trực tiếp mặt trời (日) thì MẠO hiểm quá?', 'MẠO', '冒', '["乞", "倣", "冒", "匂"]', 'Chữ「冒」(MẠO) — đương đầu với nguy hiểm, chống chọi với bệnh tật. Từ tiêu biểu: 危険を冒す（きけんをおかす）.', 25, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 17;
    IF v_ch_id IS NOT NULL THEN
        DELETE FROM kanji_exercises WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[水の中に潜る]」trong ngữ cảnh: (trốn dưới nước)', '水の中に潜る', 'みずのなかにもぐる', '["みずのなかにもぐる", "せんざいてきなちから", "せんにゅうそうさ", "ぎしんあんき"]', '「水の中に潜る」đọc là「みずのなかにもぐる」(mizunonakanimoguru) — Nghĩa: trốn dưới nước.', 1, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[物陰に潜む]」trong ngữ cảnh: (ẩn nấp trong vỏ bọc)', '物陰に潜む', 'ものかげにひそむ', '["おんしんびょうどう", "しいてきなかいしゃく", "せっしやくわん", "ものかげにひそむ"]', '「物陰に潜む」đọc là「ものかげにひそむ」(monokagenihisomu) — Nghĩa: ẩn nấp trong vỏ bọc.', 2, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[潜入捜査]」trong ngữ cảnh: (điều tra thâm nhập)', '潜入捜査', 'せんにゅうそうさ', '["いちせきのふね", "かんぺきにしあげる", "せんにゅうそうさ", "やまのふもと"]', '「潜入捜査」đọc là「せんにゅうそうさ」(sennyuusousa) — Nghĩa: điều tra thâm nhập.', 3, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[潜在的な力]」trong ngữ cảnh: (năng lực tiềm ẩn)', '潜在的な力', 'せんざいてきなちから', '["そうへき", "せんざいてきなちから", "とうなんにあう", "さわやかなえがお"]', '「潜在的な力」đọc là「せんざいてきなちから」(senzaitekinachikara) — Nghĩa: năng lực tiềm ẩn.', 4, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[帆を上げる]」trong ngữ cảnh: (căng buồm lên)', '帆を上げる', 'ほをあげる', '["ほをあげる", "そうへき", "じこけんじよく", "だんちょうのおもい"]', '「帆を上げる」đọc là「ほをあげる」(hooageru) — Nghĩa: căng buồm lên.', 5, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[帆船]」trong ngữ cảnh: (thuyền buồm)', '帆船', 'はんせん', '["おのでまきをわりる", "ゆうきがわく", "かんがいむりょう", "はんせん"]', '「帆船」đọc là「はんせん」(hansen) — Nghĩa: thuyền buồm.', 6, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[順風満帆]」trong ngữ cảnh: (thuận buồm xuôi gió)', '順風満帆', 'じゅんぷうまんぱん', '["しんしなたいど", "けんざいかする", "じゅんぷうまんぱん", "こうどう"]', '「順風満帆」đọc là「じゅんぷうまんぱん」(junpuumanpan) — Nghĩa: thuận buồm xuôi gió.', 7, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[一隻の船]」trong ngữ cảnh: (1 con thuyền)', '一隻の船', 'いちせきのふね', '["ものかげにひそむ", "いちせきのふね", "むしがわく", "あぜどう"]', '「一隻の船」đọc là「いちせきのふね」(ichisekinofune) — Nghĩa: 1 con thuyền.', 8, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[軍艦]」trong ngữ cảnh: (tàu chiến)', '軍艦', 'ぐんかん', '["ぐんかん", "ものかげにひそむ", "ようえんなじょせい", "おんせんがわく"]', '「軍艦」đọc là「ぐんかん」(gunkan) — Nghĩa: tàu chiến.', 9, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[連合艦隊]」trong ngữ cảnh: (hạm đội tàu chiến)', '連合艦隊', 'れんごうかんたい', '["あれちをかいこんする", "しんしにうけとめる", "あいまいなたいどをとる", "れんごうかんたい"]', '「連合艦隊」đọc là「れんごうかんたい」(rengoukantai) — Nghĩa: hạm đội tàu chiến.', 10, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[潜水艦]」trong ngữ cảnh: (tàu ngầm)', '潜水艦', 'せんすいかん', '["がけがくずれる", "だんがいぜっぺき", "せんすいかん", "おくする"]', '「潜水艦」đọc là「せんすいかん」(sensuikan) — Nghĩa: tàu ngầm.', 11, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[救命艇]」trong ngữ cảnh: (tàu cứu hộ)', '救命艇', 'きゅうめいてい', '["れんごうかんたい", "きゅうめいてい", "はんらんぐんをとうばつする", "じゅんぷうまんぱん"]', '「救命艇」đọc là「きゅうめいてい」(kyuumeitei) — Nghĩa: tàu cứu hộ.', 12, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[競艇]」trong ngữ cảnh: (cuộc đua thuyền máy)', '競艇', 'きょうてい', '["きょうてい", "じゅんぼくなひとがら", "かみにつやがある", "かんぺきなえんぎ"]', '「競艇」đọc là「きょうてい」(kyoutei) — Nghĩa: cuộc đua thuyền máy.', 13, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[羅列する]」trong ngữ cảnh: (liệt kê)', '羅列する', 'られつする', '["はんせん", "ちゅうようのたちば", "きょうてんどうち", "られつする"]', '「羅列する」đọc là「られつする」(raretsusuru) — Nghĩa: liệt kê.', 14, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[網羅する]」trong ngữ cảnh: (bao gồm)', '網羅する', 'もうらする', '["たいぜんとする", "なんべんいったらわかるだろう", "もうらする", "たいぜんじじゃく"]', '「網羅する」đọc là「もうらする」(mourasuru) — Nghĩa: bao gồm.', 15, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TIỀM]」(trốn dưới nước, ẩn nấp trong vỏ bọc) — Mẹo nhớ: 2 ông chồng (夫) đứng cùng nhau dưới nước ( 氵) Cả ngày ( 日) TIỀM ẩn nhiều nguy cơ?', 'TIỀM', '潜', '["帆", "隻", "艦", "潜"]', 'Chữ「潜」(TIỀM) — trốn dưới nước, ẩn nấp trong vỏ bọc. Từ tiêu biểu: 水の中に潜る（みずのなかにもぐる）.', 16, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[PHÀM]」(căng buồm lên, thuyền buồm) — Mẹo nhớ: PHÀM thì cánh buồm được làm từ vải (巾)thường (凡)?', 'PHÀM', '帆', '["艇", "羅", "帆", "艦"]', 'Chữ「帆」(PHÀM) — căng buồm lên, thuyền buồm. Từ tiêu biểu: 帆を上げる（ほをあげる）.', 17, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[CHÍCH]」(1 con thuyền) — Mẹo nhớ: 1 chú chim (隹) CHÍCH đang đứng dạng chân?', 'CHÍCH', '隻', '["遭", "隻", "羅", "盤"]', 'Chữ「隻」(CHÍCH) — 1 con thuyền. Từ tiêu biểu: 一隻の船（いちせきのふね）.', 18, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[HẠM]」(tàu chiến, hạm đội tàu chiến) — Mẹo nhớ: Tàu (舟)  Giám (監) sát biển là chiến HẠM?', 'HẠM', '艦', '["艦", "遭", "墜", "飢"]', 'Chữ「艦」(HẠM) — tàu chiến, hạm đội tàu chiến. Từ tiêu biểu: 軍艦（ぐんかん）.', 19, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[ĐĨNH]」(tàu cứu hộ, cuộc đua thuyền máy) — Mẹo nhớ: thuyền (舟) chở vật nhỏ cho triều đình (廷) thì được gọi là ĐĨNH (艇)?', 'ĐĨNH', '艇', '["飢", "餓", "湧", "艇"]', 'Chữ「艇」(ĐĨNH) — tàu cứu hộ, cuộc đua thuyền máy. Từ tiêu biểu: 救命艇（きゅうめいてい）.', 20, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[LA]」(liệt kê, bao gồm) — Mẹo nhớ: Nhìn theo Chỉ (糸  )dẫn của LA Bàn đi bắt Chim (隹)?', 'LA', '羅', '["崖", "麓", "羅", "湧"]', 'Chữ「羅」(LA) — liệt kê, bao gồm. Từ tiêu biểu: 羅列する（られつする）.', 21, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[BÀN]」(nền đất, sụt lún đất) — Mẹo nhớ: Đặt thuyền ( 舟) kẻ thù ( 殳) lên BÀN đĩa (皿)?', 'BÀN', '盤', '["坑", "盤", "麓", "窟"]', 'Chữ「盤」(BÀN) — nền đất, sụt lún đất. Từ tiêu biểu: 地盤（じばん）.', 22, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TAO]」(bị trộm cắp, bắt gặp ngẫu nhiên) — Mẹo nhớ: Mỗi ngày (日) trên đường (廴) TAO lại gặp 1 khúc nhạc（曲)?', 'TAO', '遭', '["遭", "坑", "勾", "畔"]', 'Chữ「遭」(TAO) — bị trộm cắp, bắt gặp ngẫu nhiên. Từ tiêu biểu: 盗難に遭う（とうなんにあう）.', 23, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TRỤY]」(máy bay rơi, lòng tin bị đánh mất) — Mẹo nhớ: Đội (隊) quân TRỤY lạc bị bắn rơi xuống Đất (土)?', 'TRỤY', '墜', '["畔", "堆", "伐", "墜"]', 'Chữ「墜」(TRỤY) — máy bay rơi, lòng tin bị đánh mất. Từ tiêu biểu: 飛行機が墜落する（ひこうきがついらくする）.', 24, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[CƠ]」(đói khát vì thiếu lương thực, khát khao tình yêu thương) — Mẹo nhớ: CƠ thể đói quá ăn (飠) luôn cả Ghế (几)?', 'CƠ', '飢', '["壌", "墾", "飢", "伐"]', 'Chữ「飢」(CƠ) — đói khát vì thiếu lương thực, khát khao tình yêu thương. Từ tiêu biểu: 食料がなくて飢える（しょくりょうがなくてうえる）.', 25, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 18;
    IF v_ch_id IS NOT NULL THEN
        DELETE FROM kanji_exercises WHERE chapter_id = v_ch_id;
        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[甚だ不愉快]」trong ngữ cảnh: (cực kỳ khó chịu)', '甚だ不愉快', 'はなはだふゆかい', '["はなはだふゆかい", "しゅぶそくとう", "かんせん", "るいせん"]', '「甚だ不愉快」đọc là「はなはだふゆかい」(hanahadafuyukai) — Nghĩa: cực kỳ khó chịu.', 1, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[勘違いも甚だしい]」trong ngữ cảnh: (đừng hiểu nhầm nhé)', '勘違いも甚だしい', 'かんちがいもはなはだしい', '["つばをのみこむ", "せきずい", "きこう", "かんちがいもはなはだしい"]', '「勘違いも甚だしい」đọc là「かんちがいもはなはだしい」(kanchigaimohanahadashii) — Nghĩa: đừng hiểu nhầm nhé.', 2, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[甚大な被害]」trong ngữ cảnh: (thiệt hại rất nghiêm trọng)', '甚大な被害', 'じんだいなひがい', '["しいたけ", "せきついどうぶつ", "じんだいなひがい", "にいがたけん"]', '「甚大な被害」đọc là「じんだいなひがい」(jindainahigai) — Nghĩa: thiệt hại rất nghiêm trọng.', 3, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[僅かな変化]」trong ngữ cảnh: (thay đổi nhỏ)', '僅かな変化', 'わずかなへんか', '["かいとうらんま", "わずかなへんか", "びこうをふくらませる", "かまでくさをかる"]', '「僅かな変化」đọc là「わずかなへんか」(wazukanahenka) — Nghĩa: thay đổi nhỏ.', 4, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[僅差]」trong ngữ cảnh: (suýt soát, cách biệt nhỏ)', '僅差', 'きんさ', '["きんさ", "じゅうおうむじん", "顎関節症がくかんせつしょう", "のうにしゅようができる"]', '「僅差」đọc là「きんさ」(kinsa) — Nghĩa: suýt soát, cách biệt nhỏ.', 5, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[食欲が旺盛]」trong ngữ cảnh: (thèm ăn)', '食欲が旺盛', 'しょくよくがおうせい', '["でんこうせっか", "へんぼうする", "せんてひっしょう", "しょくよくがおうせい"]', '「食欲が旺盛」đọc là「しょくよくがおうせい」(shokuyokugaousei) — Nghĩa: thèm ăn.', 6, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[好奇心旺盛]」trong ngữ cảnh: (tính tò mò, hiếu kỳ)', '好奇心旺盛', 'こうきしんおうせい', '["けっこん", "なきはらす", "こうきしんおうせい", "ちょうねんてん"]', '「好奇心旺盛」đọc là「こうきしんおうせい」(koukishinousei) — Nghĩa: tính tò mò, hiếu kỳ.', 7, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[寡占]」trong ngữ cảnh: (độc quyền)', '寡占', 'かせん', '["またわり", "かせん", "うすときね", "けんじゅう"]', '「寡占」đọc là「かせん」(kasen) — Nghĩa: độc quyền.', 8, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[寡作な画家]」trong ngữ cảnh: (họa sĩ có ít tác phẩm)', '寡作な画家', 'かさくながか', '["かさくながか", "またわり", "にぎりこぶし", "かくせいする"]', '「寡作な画家」đọc là「かさくながか」(kasakunagaka) — Nghĩa: họa sĩ có ít tác phẩm.', 9, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[寡黙な人]」trong ngữ cảnh: (người hay ngượng ngùng)', '寡黙な人', 'かもくなひと', '["けんぽう", "すいとう", "いんとうがん", "かもくなひと"]', '「寡黙な人」đọc là「かもくなひと」(kamokunahito) — Nghĩa: người hay ngượng ngùng.', 10, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[風貌]」trong ngữ cảnh: (diện mạo, vẻ bề ngoài)', '風貌', 'ふうぼう', '["だぼくしょう", "ひにょうきか", "ふうぼう", "ちょとつもうしん"]', '「風貌」đọc là「ふうぼう」(fuubou) — Nghĩa: diện mạo, vẻ bề ngoài.', 11, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[美貌]」trong ngữ cảnh: (khuôn mặt đẹp)', '美貌', 'びぼう', '["こつにくしゅ", "びぼう", "こぐんふんとう", "ふうぼう"]', '「美貌」đọc là「びぼう」(bibou) — Nghĩa: khuôn mặt đẹp.', 12, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[変貌する]」trong ngữ cảnh: (biến đổi)', '変貌する', 'へんぼうする', '["へんぼうする", "けんこんいってき", "がでんいんすい", "ほねのずい"]', '「変貌する」đọc là「へんぼうする」(henbousuru) — Nghĩa: biến đổi.', 13, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[ダイエットをして5kg痩やせた]」trong ngữ cảnh: (đã giảm 5kg nhờ ăn kiêng)', 'ダイエットをして5kg痩やせた', 'ダイエットをして5kg痩やせた', '["ほねのずい", "顎あご", "こうきしんおうせい", "ダイエットをして5kg痩やせた"]', '「ダイエットをして5kg痩やせた」đọc là「ダイエットをして5kg痩やせた」(daiettooshite5kg痩yaseta) — Nghĩa: đã giảm 5kg nhờ ăn kiêng.', 14, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[痩やせた土地]」trong ngữ cảnh: (vùng đất khô cằn)', '痩やせた土地', '痩やせたとち', '["かもくなひと", "ざんがい", "痩やせたとち", "痩身そうしんグッズ"]', '「痩やせた土地」đọc là「痩やせたとち」(痩yasetatochi) — Nghĩa: vùng đất khô cằn.', 15, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[THẬM]」(cực kỳ khó chịu, đừng hiểu nhầm nhé) — Mẹo nhớ: bốn (匹) lần ngọt (甘) thì cực kì kinh khủng, THẬM tệ?', 'THẬM', '甚', '["僅", "旺", "寡", "甚"]', 'Chữ「甚」(THẬM) — cực kỳ khó chịu, đừng hiểu nhầm nhé. Từ tiêu biểu: 甚だ不愉快（はなはだふゆかい）.', 16, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[CẬN]」(thay đổi nhỏ, suýt soát) — Mẹo nhớ: Chỉ có CẬN thần mới dám đút Cỏ (艹) vào Miệng (口) Vua (王)?', 'CẬN', '僅', '["貌", "痩", "僅", "寡"]', 'Chữ「僅」(CẬN) — thay đổi nhỏ, suýt soát. Từ tiêu biểu: 僅かな変化（わずかなへんか）.', 17, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[VƯỢNG]」(thèm ăn, tính tò mò) — Mẹo nhớ: Tỷ phú Nhật (日) VƯỢNG (王)?', 'VƯỢNG', '旺', '["髄", "旺", "痩", "泌"]', 'Chữ「旺」(VƯỢNG) — thèm ăn, tính tò mò. Từ tiêu biểu: 食欲が旺盛（しょくよくがおうせい）.', 18, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[QUẢ]」(độc quyền, họa sĩ có ít tác phẩm) — Mẹo nhớ: QUẢ phụ là người phân chia (分) hàng trăm (百)công việc trong nhà (宀)?', 'QUẢ', '寡', '["寡", "髄", "脊", "椎"]', 'Chữ「寡」(QUẢ) — độc quyền, họa sĩ có ít tác phẩm. Từ tiêu biểu: 寡占（かせん）.', 19, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[MẠO]」(diện mạo, khuôn mặt đẹp) — Mẹo nhớ: con sâu (豸) màu trắng có 2 chân (皃) dung MẠO khá đẹp?', 'MẠO', '貌', '["椎", "胞", "孔", "貌"]', 'Chữ「貌」(MẠO) — diện mạo, khuôn mặt đẹp. Từ tiêu biểu: 風貌（ふうぼう）.', 20, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[SẤU]」(đã giảm 5kg nhờ ăn kiêng, vùng đất khô cằn) — Mẹo nhớ: Đã Ốm rồi còn phải lê hai chân ra Ruộng cầy thì bảo sao không GẦY và xấu gái như con cá SẤU?', 'SẤU', '痩', '["顎", "咽", "痩", "孔"]', 'Chữ「痩」(SẤU) — đã giảm 5kg nhờ ăn kiêng, vùng đất khô cằn. Từ tiêu biểu: ダイエットをして5kg痩やせた（ダイエットをして5kg痩やせた）.', 21, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[BÍ]」(bài tiết hoóc môn, khoa tiết niệu) — Mẹo nhớ: BÍ quá thì phải bài tiết là điều tất (必) yếu?', 'BÍ', '泌', '["拳", "泌", "咽", "唾"]', 'Chữ「泌」(BÍ) — bài tiết hoóc môn, khoa tiết niệu. Từ tiêu biểu: 分泌（ぶんぴつ）.', 22, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TỦY]」(cấy ghép tủy, tủy xương) — Mẹo nhớ: Xương (骨)có (有) đường (辶) dẫn bên trong là TỦY?', 'TỦY', '髄', '["髄", "拳", "股", "腺"]', 'Chữ「髄」(TỦY) — cấy ghép tủy, tủy xương. Từ tiêu biểu: 骨髄移植（こつずいいしょく）.', 23, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TÍCH]」(dây tủy sống, cột sống lưng) — Mẹo nhớ: Trong người (人) chị nguyệt (月) TÍCH tụ 4 cái đốt sống?', 'TÍCH', '脊', '["腺", "癒", "篤", "脊"]', 'Chữ「脊」(TÍCH) — dây tủy sống, cột sống lưng. Từ tiêu biểu: 脊髄（せきずい）.', 24, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[CHUY]」(động vật có xương sống, thoát vị đĩa đệm) — Mẹo nhớ: Dùng cây gỗ (木) đánh con chim (隹CHUY)?', 'CHUY', '椎', '["剖", "醒", "椎", "篤"]', 'Chữ「椎」(CHUY) — động vật có xương sống, thoát vị đĩa đệm. Từ tiêu biểu: 脊椎動物（せきついどうぶつ）.', 25, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 19;
