        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[近畿地方]」trong ngữ cảnh: (Vùng Kinki là một khu vực nằm ở phía tây trung tâm của Honshu)', '近畿地方', 'きんきちほう', '["きんきちほう", "ちょくし", "みぞうのだいじしん", "いっしんいったい"]', '「近畿地方」đọc là「きんきちほう」(kinkichihou) — Nghĩa: Vùng Kinki là một khu vực nằm ở phía tây trung tâm của Honshu.', 1, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[滋養]」trong ngữ cảnh: (chất dinh dưỡng)', '滋養', 'じよう', '["だいかんみんこく", "ろうおう", "にるいだをはなつ", "じよう"]', '「滋養」đọc là「じよう」(jiyou) — Nghĩa: chất dinh dưỡng.', 2, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[滋賀県]」trong ngữ cảnh: (tỉnh Siga)', '滋賀県', 'しがけん', '["しょうい‐ちゅうい‐たいい", "わこうどうじん", "しがけん", "ゆいがどくそん"]', '「滋賀県」đọc là「しがけん」(shigaken) — Nghĩa: tỉnh Siga.', 3, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[刹那的]」trong ngữ cảnh: (mang tính khoảnh khắc)', '刹那的', 'せつなてき', '["せんぺんばんか", "せつなてき", "そうすい", "しゅひん"]', '「刹那的」đọc là「せつなてき」(setsunateki) — Nghĩa: mang tính khoảnh khắc.', 4, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[旦那]」trong ngữ cảnh: (chồng)', '旦那', 'だんな', '["だんな", "いちぶいちりん", "むがむちゅう", "こうはん"]', '「旦那」đọc là「だんな」(danna) — Nghĩa: chồng.', 5, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[必須な]」trong ngữ cảnh: (bắt buộc)', '必須な', 'ひっすな', '["ぼうしのはつげん", "ちゃくし", "ばっぽんそくげん", "ひっすな"]', '「必須な」đọc là「ひっすな」(hissuna) — Nghĩa: bắt buộc.', 6, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[急須]」trong ngữ cảnh: (ấm trà nhỏ bằng gốm sứ)', '急須', 'きゅうす', '["しめんそか", "おもてざた", "きゅうす", "きゅうてんちょっか"]', '「急須」đọc là「きゅうす」(kyuusu) — Nghĩa: ấm trà nhỏ bằng gốm sứ.', 7, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[必須科目]」trong ngữ cảnh: (môn học cần thiết)', '必須科目', 'ひっすかもく', '["ちゃくちゃくとつづく", "ひっすかもく", "ほうそう", "ぼうしょ"]', '「必須科目」đọc là「ひっすかもく」(hissukamoku) — Nghĩa: môn học cần thiết.', 8, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[曽祖父母]」trong ngữ cảnh: (cụ ông cụ bà)', '曽祖父母', 'そうそふはは', '["そうそふはは", "ちょうだいする", "こくひん", "ひっすな"]', '「曽祖父母」đọc là「そうそふはは」(sousofuhaha) — Nghĩa: cụ ông cụ bà.', 9, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[未曽有の大地震]」trong ngữ cảnh: (trận động đất lớn chưa từng thấy)', '未曽有の大地震', 'みぞうのだいじしん', '["ふきする", "ききいっぱつ", "りゅうげんひご", "みぞうのだいじしん"]', '「未曽有の大地震」đọc là「みぞうのだいじしん」(mizounodaijishin) — Nghĩa: trận động đất lớn chưa từng thấy.', 10, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[木曽川]」trong ngữ cảnh: (sông Kiso)', '木曽川', 'きそがわ', '["たりきほんがん", "ひんきゃくをもてなす", "きそがわ", "りゅうげんひご"]', '「木曽川」đọc là「きそがわ」(kisogawa) — Nghĩa: sông Kiso.', 11, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[汎用性]」trong ngữ cảnh: (tính đa năng)', '汎用性', 'はんようせい', '["ほんまつてんとう", "はんようせい", "しゅっけしてそうりょになる", "かんこく"]', '「汎用性」đọc là「はんようせい」(hanyousei) — Nghĩa: tính đa năng.', 12, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[広汎]」trong ngữ cảnh: (phạm vi rộng)', '広汎', 'こうはん', '["こうはん", "じゅうそう", "ふわらいどう", "しゃちょうのおんぞうし"]', '「広汎」đọc là「こうはん」(kouhan) — Nghĩa: phạm vi rộng.', 13, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[沙汰を待つ]」trong ngữ cảnh: (chờ mệnh lệnh, chỉ thị)', '沙汰を待つ', 'さたをまつ', '["しゃちょうのおんぞうし", "ごい", "てんかいふく", "さたをまつ"]', '「沙汰を待つ」đọc là「さたをまつ」(sataomatsu) — Nghĩa: chờ mệnh lệnh, chỉ thị.', 14, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[音沙汰ない]」trong ngữ cảnh: (bặt vô ấm tín)', '音沙汰ない', 'おとさたない', '["にっしんげっぽ", "ひっすかもく", "おとさたない", "じごうじとく"]', '「音沙汰ない」đọc là「おとさたない」(otosatanai) — Nghĩa: bặt vô ấm tín.', 15, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[KÌ]」(Vùng Kinki là một khu vực nằm ở phía tây trung tâm của Honshu) — Mẹo nhớ: Chốn kinh KÌ, làm ruộng đồng (田) hoàn toàn bằng cơ khí (幾), máy móc!?', 'KÌ', '畿', '["滋", "那", "須", "畿"]', 'Chữ「畿」(KÌ) — Vùng Kinki là một khu vực nằm ở phía tây trung tâm của Honshu. Từ tiêu biểu: 近畿地方（きんきちほう）.', 16, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TƯ]」(chất dinh dưỡng, tỉnh Siga) — Mẹo nhớ: trời mưa hai đôi yêu nhau uống sữa tâm TƯ riêng?', 'TƯ', '滋', '["曽", "汎", "滋", "須"]', 'Chữ「滋」(TƯ) — chất dinh dưỡng, tỉnh Siga. Từ tiêu biểu: 滋養（じよう）.', 17, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[NA]」(mang tính khoảnh khắc, chồng) — Mẹo nhớ: 印度支那 ấn độ chi NA ：đông dương?', 'NA', '那', '["塁", "那", "汎", "沙"]', 'Chữ「那」(NA) — mang tính khoảnh khắc, chồng. Từ tiêu biểu: 刹那的（せつなてき）.', 18, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TU]」(bắt buộc, ấm trà nhỏ bằng gốm sứ) — Mẹo nhớ: Đi TU để Tóc (彡) trên Đầu (頁) Chắc là người vẫn nặng sầu tương tư?', 'TU', '須', '["須", "塁", "韓", "厘"]', 'Chữ「須」(TU) — bắt buộc, ấm trà nhỏ bằng gốm sứ. Từ tiêu biểu: 必須な（ひっすな）.', 19, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TẰNG]」(cụ ông cụ bà, trận động đất lớn chưa từng thấy) — Mẹo nhớ: Ngày (日) nào cũng làm Ruộng (田) mà Cỏ (艹) vẫn mọc lên TẰNG Tằng?', 'TẰNG', '曽', '["厘", "附", "彙", "曽"]', 'Chữ「曽」(TẰNG) — cụ ông cụ bà, trận động đất lớn chưa từng thấy. Từ tiêu biểu: 曽祖父母（そうそふはは）.', 20, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[PHIẾM]」(tính đa năng, phạm vi rộng) — Mẹo nhớ: Thủy (氵) nói chuyện Phàm (凡) PHIẾM?', 'PHIẾM', '汎', '["逓", "某", "汎", "彙"]', 'Chữ「汎」(PHIẾM) — tính đa năng, phạm vi rộng. Từ tiêu biểu: 汎用性（はんようせい）.', 21, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[SA]」(chờ mệnh lệnh, bặt vô ấm tín) — Mẹo nhớ: SA mạc là nơi Thiếu (少 ) Nước ( 氵)?', 'SA', '沙', '["赦", "沙", "某", "羞"]', 'Chữ「沙」(SA) — chờ mệnh lệnh, bặt vô ấm tín. Từ tiêu biểu: 沙汰を待つ（さたをまつ）.', 22, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[LŨY]」(điểm chạm bóng số 1(bóng chày), thực hiện cú đúp (bóng chày)) — Mẹo nhớ: Thành LŨY bao gồm Ruộng (田) Đất (土) vây quanh tứ phướng 4 hướng?', 'LŨY', '塁', '["塁", "赦", "丙", "喩"]', 'Chữ「塁」(LŨY) — điểm chạm bóng số 1(bóng chày), thực hiện cú đúp (bóng chày). Từ tiêu biểu: 一塁ベース（いちるいベース）.', 23, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[HÀN]」(Hàn Quốc, Đại hàn dân quốc) — Mẹo nhớ: 20 ngày (十日十)  Vi (韋) hành của vua HÀN quốc?', 'HÀN', '韓', '["喩", "哺", "侶", "韓"]', 'Chữ「韓」(HÀN) — Hàn Quốc, Đại hàn dân quốc. Từ tiêu biểu: 韓国（かんこく）.', 24, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[LI]」(0, rất nhỏ) — Mẹo nhớ: Ông Lí ( 里) Chi LI từng Tí?', 'LI', '厘', '["戴", "賓", "厘", "侶"]', 'Chữ「厘」(LI) — 0, rất nhỏ. Từ tiêu biểu: 厘（りん）.', 25, NOW());
    END IF;
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 20;
    IF v_ch_id IS NOT NULL THEN
