        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[詔書]」trong ngữ cảnh: (chiếu thư)', '詔書', 'しょうしょ', '["しょうしょ", "じゃくしゃをぐろうする", "ぞうをいる", "いがた"]', '「詔書」đọc là「しょうしょ」(shousho) — Nghĩa: chiếu thư.', 1, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[国王に謁見する]」trong ngữ cảnh: (yết kiến quốc vương)', '国王に謁見する', 'こくおうにえっけんする', '["いきしょうちん", "ぎしんあんき", "しょうこいんぺい", "こくおうにえっけんする"]', '「国王に謁見する」đọc là「こくおうにえっけんする」(kokuouniekkensuru) — Nghĩa: yết kiến quốc vương.', 2, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[謁見の間]」trong ngữ cảnh: (hội trường yết kiến vua)', '謁見の間', 'えっけんのあいだ', '["おんしんびょうどう", "せっしやくわん", "えっけんのあいだ", "かんむりょう"]', '「謁見の間」đọc là「えっけんのあいだ」(ekkennoaida) — Nghĩa: hội trường yết kiến vua.', 3, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[皇帝に拝謁する]」trong ngữ cảnh: (diện kiến hoàng đế)', '皇帝に拝謁する', 'こうていにはいえつする', '["どうけいをだく", "こうていにはいえつする", "きんこかたちにしょす", "ふねのうげんさげんにあかりをともす"]', '「皇帝に拝謁する」đọc là「こうていにはいえつする」(kouteinihaietsusuru) — Nghĩa: diện kiến hoàng đế.', 4, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[朕は天子の自称]」trong ngữ cảnh: (trẫm là tự xưng của hoàng thượng)', '朕は天子の自称', 'ちんはてんしのじしょう', '["ちんはてんしのじしょう", "しょうしょ", "こうていにはいえつする", "えっけんのあいだ"]', '「朕は天子の自称」đọc là「ちんはてんしのじしょう」(chinhatenshinojishou) — Nghĩa: trẫm là tự xưng của hoàng thượng.', 5, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[赤字を補填する]」trong ngữ cảnh: (bù lỗ)', '赤字を補填する', 'あかじをほてんする', '["ガスがすのじゅうてん", "きんきじゃくやく", "めいよきそん", "あかじをほてんする"]', '「赤字を補填する」đọc là「あかじをほてんする」(akajiohotensuru) — Nghĩa: bù lỗ.', 6, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[ガスの充填]」trong ngữ cảnh: (bơm khí gas)', 'ガスの充填', 'ガスがすのじゅうてん', '["いきとうごう", "ひふんこうがい", "ガスがすのじゅうてん", "らつわんをふるう"]', '「ガスの充填」đọc là「ガスがすのじゅうてん」(gasugasunojuuten) — Nghĩa: bơm khí gas.', 7, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[斑点]」trong ngữ cảnh: (vết nám, đốm trên da)', '斑点', 'はんてん', '["こくおうにえっけんする", "はんてん", "ひふんこうがい", "うっとうしい"]', '「斑点」đọc là「はんてん」(hanten) — Nghĩa: vết nám, đốm trên da.', 8, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[蒙古斑]」trong ngữ cảnh: (vết bớt màu xanh ở trẻ sơ sinh)', '蒙古斑', 'もうこはん', '["もうこはん", "あかじをほてんする", "まだらもよう", "きょうきらんぶ"]', '「蒙古斑」đọc là「もうこはん」(moukohan) — Nghĩa: vết bớt màu xanh ở trẻ sơ sinh.', 9, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[斑模様]」trong ngữ cảnh: (họa tiết lốm đốm)', '斑模様', 'まだらもよう', '["せんりつ", "はたけのうねをつくる", "あいきこつりつ", "まだらもよう"]', '「斑模様」đọc là「まだらもよう」(madaramoyou) — Nghĩa: họa tiết lốm đốm.', 10, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[戦慄]」trong ngữ cảnh: (rùng mình, kinh hãi)', '戦慄', 'せんりつ', '["きょうてんどうち", "ぐびじんそう", "せんりつ", "げんとうをかかげる"]', '「戦慄」đọc là「せんりつ」(senritsu) — Nghĩa: rùng mình, kinh hãi.', 11, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[他人の気持ちを弄ぶ]」trong ngữ cảnh: (đùa giỡn với cảm xúc của người khác)', '他人の気持ちを弄ぶ', 'たにんのきもちをもてあそぶ', '["いっきいちゆう", "たにんのきもちをもてあそぶ", "こくじ", "はんてん"]', '「他人の気持ちを弄ぶ」đọc là「たにんのきもちをもてあそぶ」(taninnokimochiomoteasobu) — Nghĩa: đùa giỡn với cảm xúc của người khác.', 12, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[弱者を愚弄する]」trong ngữ cảnh: (chế giễu người yếu đuối)', '弱者を愚弄する', 'じゃくしゃをぐろうする', '["じゃくしゃをぐろうする", "せんせんきょうきょう", "ほうふくぜっとう", "れいせいちんちゃく"]', '「弱者を愚弄する」đọc là「じゃくしゃをぐろうする」(jakushaogurousuru) — Nghĩa: chế giễu người yếu đuối.', 13, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[運命に翻弄される]」trong ngữ cảnh: (chịu sự đùa giỡn của số phận)', '運命に翻弄される', 'うんめいにほんろうされる', '["れいせいちんちゃく", "ひよくなとち", "ちんはてんしのじしょう", "うんめいにほんろうされる"]', '「運命に翻弄される」đọc là「うんめいにほんろうされる」(unmeinihonrousareru) — Nghĩa: chịu sự đùa giỡn của số phận.', 14, NOW()),
        (v_ch_id, 'READING', 'Chọn cách đọc Hiragana chính xác cho từ「[憧憬を抱く]」trong ngữ cảnh: (ấp ủ khát vọng)', '憧憬を抱く', 'どうけいをだく', '["もうこはん", "たじょうたこん", "どうけいをだく", "はんしんはんぎ"]', '「憧憬を抱く」đọc là「どうけいをだく」(doukeiodaku) — Nghĩa: ấp ủ khát vọng.', 15, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TRIỆU]」(chiếu chỉ, chiếu thư) — Mẹo nhớ: chiếu vua ban như lời nói (言) TRIỆU (召) hồi?', 'TRIỆU', '詔', '["謁", "朕", "填", "詔"]', 'Chữ「詔」(TRIỆU) — chiếu chỉ, chiếu thư. Từ tiêu biểu: 詔（みことのり）.', 16, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[YẾT]」(yết kiến quốc vương, hội trường yết kiến vua) — Mẹo nhớ: Vào YẾT (謁) kiến, nói chuyện (言) về cái thìa (匕) để trong bao (勹) cả ngày (日) bị bốc mùi (匂)?', 'YẾT', '謁', '["斑", "慄", "謁", "填"]', 'Chữ「謁」(YẾT) — yết kiến quốc vương, hội trường yết kiến vua. Từ tiêu biểu: 国王に謁見する（こくおうにえっけんする）.', 17, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[TRẪM]」(trẫm là tự xưng của hoàng thượng) — Mẹo nhớ: ngẩng mặt lên trời (天)  ngắm ánh (丷)  trăng (月)  tự xưng TRẪM (朕)?', 'TRẪM', '朕', '["憬", "朕", "慄", "弄"]', 'Chữ「朕」(TRẪM) — trẫm là tự xưng của hoàng thượng. Từ tiêu biểu: 朕は天子の自称（ちんはてんしのじしょう）.', 18, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[ĐIỀN]」(bù lỗ, bơm khí gas) — Mẹo nhớ: dùng đúng 10 (十) cái dụng cụ (具) để ĐIỀN đầy vào chỗ trống trên đất ( 土)?', 'ĐIỀN', '填', '["填", "憬", "毀", "蔽"]', 'Chữ「填」(ĐIỀN) — bù lỗ, bơm khí gas. Từ tiêu biểu: 赤字を補填する（あかじをほてんする）.', 19, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[BAN]」(vết nám, vết bớt màu xanh ở trẻ sơ sinh) — Mẹo nhớ: 2 nhà Vua (王) ép làm Văn (文) sẽ bị sốt phát BAN?', 'BAN', '斑', '["蔽", "鬱", "沃", "斑"]', 'Chữ「斑」(BAN) — vết nám, vết bớt màu xanh ở trẻ sơ sinh. Từ tiêu biểu: 斑点（はんてん）.', 20, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[LẬT]」(rùng mình) — Mẹo nhớ: LẬT em gái tây (西) dưới gốc (木) cây tim (忄) đập run rẩy?', 'LẬT', '慄', '["辣", "舷", "慄", "沃"]', 'Chữ「慄」(LẬT) — rùng mình. Từ tiêu biểu: 戦慄（せんりつ）.', 21, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[LỘNG]」(đùa giỡn với cảm xúc của người khác, chế giễu người yếu đuối) — Mẹo nhớ: bó tay ( 廾 ) ông vua (王) LỘNG hành?', 'LỘNG', '弄', '["瑠", "弄", "舷", "冶"]', 'Chữ「弄」(LỘNG) — đùa giỡn với cảm xúc của người khác, chế giễu người yếu đuối. Từ tiêu biểu: 他人の気持ちを弄ぶ（たにんのきもちをもてあそぶ）.', 22, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[CẢNH]」(ấp ủ khát vọng) — Mẹo nhớ: CẢNH (景) tình xuất phái từ trái tim (忄)?', 'CẢNH', '憬', '["憬", "瑠", "璃", "錮"]', 'Chữ「憬」(CẢNH) — ấp ủ khát vọng. Từ tiêu biểu: 憧憬を抱く（どうけいをだく）.', 23, NOW()),
        (v_ch_id, 'WRITING', 'Chữ Hán nào mang âm Hán Việt「[HỦY]」(phỉ báng/ tổn hại danh dự) — Mẹo nhớ: dùng Vũ khí (殳)  phá HUỶ cái cối xay (臼)  bằng Đất (土)?', 'HỦY', '毀', '["錮", "璽", "鋳", "毀"]', 'Chữ「毀」(HỦY) — phỉ báng/ tổn hại danh dự. Từ tiêu biểu: 名誉毀損（めいよきそん）.', 24, NOW()),
