END $$;

-- 5. SEED 20 MINIGAME TÌNH HUỐNG CHUYÊN ĐỀ N1
DO $$
DECLARE v_ch_id BIGINT; BEGIN
    SELECT id INTO v_ch_id FROM kanji_chapters WHERE jlpt_level = 'N1' AND chapter_number = 1;
    IF v_ch_id IS NOT NULL THEN
