INSERT INTO kanji_achievement_tests (stage, title, description, pass_percentage, test_data_json, display_order, created_at) VALUES
(22, 'Achievement Test 1 N1 (Chuyên đề 1・2)', 'Đề kiểm tra định kỳ Kanji Master N1 tổng hợp kiến thức Chuyên đề 1 và Chuyên đề 2 (Thang điểm 100, đạt ≥ 85% để qua chặng).', 85, '{"level": "N1", "chapters": [1, 2], "totalPoints": 100, "timeLimitMinutes": 25, "questions": [{"id": 1, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[行為]」trong ngữ cảnh: (Hành vi)", "targetWord": "行為", "correctAnswer": "こうい", "options": ["こうい", "せいけんをだっかいする", "しゅぶそくとう", "ちょうやく"], "explanation": "「行為」đọc là「こうい」(koui) — Nghĩa: Hành vi."}, {"id": 2, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[不正行為]」trong ngữ cảnh: (Hành vi bất chính)", "targetWord": "不正行為", "correctAnswer": "ふせいこうい", "options": ["はねる", "きゅうに黙りこむ", "いんきょする", "ふせいこうい"], "explanation": "「不正行為」đọc là「ふせいこうい」(fuseikoui) — Nghĩa: Hành vi bất chính."}, {"id": 3, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[扱う]」trong ngữ cảnh: (Xử lý, đối xử, sử dụng)", "targetWord": "扱う", "correctAnswer": "あつかう", "options": ["はいきガス", "けいじする", "あつかう", "ちょうば"], "explanation": "「扱う」đọc là「あつかう」(atsukau) — Nghĩa: Xử lý, đối xử, sử dụng."}, {"id": 4, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[取扱説明書]」trong ngữ cảnh: (Sách hướng dẫn sử dụng)", "targetWord": "取扱説明書", "correctAnswer": "とりあつかいせつめいしょ", "options": ["すがたをかくす", "とりあつかいせつめいしょ", "くしする", "さんかこくごをあやつる"], "explanation": "「取扱説明書」đọc là「とりあつかいせつめいしょ」(toriatsukaisetsumeisho) — Nghĩa: Sách hướng dẫn sử dụng."}, {"id": 5, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[披露]」trong ngữ cảnh: (Công khai, thể hiện)", "targetWord": "披露", "correctAnswer": "ひろう", "options": ["ひろう", "ほうにていしょくする", "さえぎる", "かみをさく"], "explanation": "「披露」đọc là「ひろう」(hirou) — Nghĩa: Công khai, thể hiện."}, {"id": 6, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[抑える]」trong ngữ cảnh: (Kiềm chế)", "targetWord": "抑える", "correctAnswer": "おさえる", "options": ["かかげる", "あきらめがつかない", "たいしんこうぞう", "おさえる"], "explanation": "「抑える」đọc là「おさえる」(osaeru) — Nghĩa: Kiềm chế."}, {"id": 7, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[抑圧]」trong ngữ cảnh: (Đàn áp, chèn ép)", "targetWord": "抑圧", "correctAnswer": "よくあつ", "options": ["しっせきする", "じゅうおうむじん", "よくあつ", "かいとうらんま"], "explanation": "「抑圧」đọc là「よくあつ」(yokuatsu) — Nghĩa: Đàn áp, chèn ép."}, {"id": 8, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[抑制]」trong ngữ cảnh: (Kiềm chế)", "targetWord": "抑制", "correctAnswer": "よくせい", "options": ["しょうひんにけっかんがある", "よくせい", "ゆれる", "じょうほ"], "explanation": "「抑制」đọc là「よくせい」(yokusei) — Nghĩa: Kiềm chế."}, {"id": 9, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[法に抵触する]」trong ngữ cảnh: (Vi phạm (luật), xung đột)", "targetWord": "法に抵触する", "correctAnswer": "ほうにていしょくする", "options": ["ほうにていしょくする", "ふこうにおとしいれる", "でんこうせっか", "どうようする"], "explanation": "「法に抵触する」đọc là「ほうにていしょくする」(houniteishokusuru) — Nghĩa: Vi phạm (luật), xung đột."}, {"id": 10, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[大抵]」trong ngữ cảnh: (Nói chung, thường)", "targetWord": "大抵", "correctAnswer": "たいてい", "options": ["どうようする", "ひしょち", "こうそう", "たいてい"], "explanation": "「大抵」đọc là「たいてい」(taitei) — Nghĩa: Nói chung, thường."}, {"id": 11, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[借金の返済期限が迫る]」trong ngữ cảnh: (thời hạn trả nợ đang tới gàn)", "targetWord": "借金の返済期限が迫る", "correctAnswer": "しゃっきんのへんさいきげんがせまる", "options": ["しゃっきんのへんさいきげんがせまる", "こんいんとどけ", "しゅっぽんする", "えんぎがいい"], "explanation": "「借金の返済期限が迫る」đọc là「しゃっきんのへんさいきげんがせまる」(shakkinnohensaikigengasemaru) — Nghĩa: thời hạn trả nợ đang tới gàn."}, {"id": 12, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[脅迫される]」trong ngữ cảnh: (bị đe dọa)", "targetWord": "脅迫される", "correctAnswer": "きょうはくされる", "options": ["いっしんいったい", "いちまつのふあんがよぎる", "むすめにむこをとる", "きょうはくされる"], "explanation": "「脅迫される」đọc là「きょうはくされる」(kyouhakusareru) — Nghĩa: bị đe dọa."}, {"id": 13, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[迫害を受ける]」trong ngữ cảnh: (bị khủng bố)", "targetWord": "迫害を受ける", "correctAnswer": "はくがいをうける", "options": ["くつがえす", "ねんれいをいつわる", "はくがいをうける", "たんがんしょ"], "explanation": "「迫害を受ける」đọc là「はくがいをうける」(hakugaioukeru) — Nghĩa: bị khủng bố."}, {"id": 14, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[胸を圧迫される]」trong ngữ cảnh: (bị tức ngực)", "targetWord": "胸を圧迫される", "correctAnswer": "むねをあっぱくされる", "options": ["はじをしのぶ", "むねをあっぱくされる", "きょういてきなきろく", "おじ"], "explanation": "「胸を圧迫される」đọc là「むねをあっぱくされる」(muneoappakusareru) — Nghĩa: bị tức ngực."}, {"id": 15, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[当初の目的を遂げる]」trong ngữ cảnh: (đạt được mục tiêu ban đầu)", "targetWord": "当初の目的を遂げる", "correctAnswer": "とうしょのもくてきをとげる", "options": ["とうしょのもくてきをとげる", "ほうびをやる", "しんちょう", "ゆいがどくそん"], "explanation": "「当初の目的を遂げる」đọc là「とうしょのもくてきをとげる」(toushonomokutekiotogeru) — Nghĩa: đạt được mục tiêu ban đầu."}, {"id": 16, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[進歩を遂げる]」trong ngữ cảnh: (có sự tiến bộ)", "targetWord": "進歩を遂げる", "correctAnswer": "しんぽをとげる", "options": ["わこうどうじん", "こうふんする", "ほめたたえる", "しんぽをとげる"], "explanation": "「進歩を遂げる」đọc là「しんぽをとげる」(shinpootogeru) — Nghĩa: có sự tiến bộ."}, {"id": 17, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[任務を遂行する]」trong ngữ cảnh: (thực hiện nhiệm vụ)", "targetWord": "任務を遂行する", "correctAnswer": "にんむをすいこうする", "options": ["おば", "はさまる", "にんむをすいこうする", "せんぺんばんか"], "explanation": "「任務を遂行する」đọc là「にんむをすいこうする」(ninmuosuikousuru) — Nghĩa: thực hiện nhiệm vụ."}, {"id": 18, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[自殺未遂]」trong ngữ cảnh: (tự tử không thành)", "targetWord": "自殺未遂", "correctAnswer": "じさつみすい", "options": ["くだける", "じさつみすい", "ほんそうする", "せきはいする"], "explanation": "「自殺未遂」đọc là「じさつみすい」(jisatsumisui) — Nghĩa: tự tử không thành."}, {"id": 19, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[抽象画]」trong ngữ cảnh: (tranh trừu tượng)", "targetWord": "抽象画", "correctAnswer": "ちゅうしょうが", "options": ["ちゅうしょうが", "かくじつ", "いあんりょこう", "かけい"], "explanation": "「抽象画」đọc là「ちゅうしょうが」(chuushouga) — Nghĩa: tranh trừu tượng."}, {"id": 20, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[抽象的な]」trong ngữ cảnh: (mang tính trừu tượng)", "targetWord": "抽象的な", "correctAnswer": "ちゅうしょうてきな", "options": ["かけい", "てんがい", "きがくるう", "ちゅうしょうてきな"], "explanation": "「抽象的な」đọc là「ちゅうしょうてきな」(chuushoutekina) — Nghĩa: mang tính trừu tượng."}]}', 22, NOW());
INSERT INTO kanji_achievement_tests (stage, title, description, pass_percentage, test_data_json, display_order, created_at) VALUES
(23, 'Achievement Test 2 N1 (Chuyên đề 3・4)', 'Đề kiểm tra định kỳ Kanji Master N1 tổng hợp kiến thức Chuyên đề 3 và Chuyên đề 4 (Thang điểm 100, đạt ≥ 85% để qua chặng).', 85, '{"level": "N1", "chapters": [3, 4], "totalPoints": 100, "timeLimitMinutes": 25, "questions": [{"id": 1, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[家業を継ぐ]」trong ngữ cảnh: (kế nghiệp gia dình)", "targetWord": "家業を継ぐ", "correctAnswer": "かぎょうをつぐ", "options": ["かぎょうをつぐ", "ぎしんあんき", "じょうもんじだい", "さといも"], "explanation": "「家業を継ぐ」đọc là「かぎょうをつぐ」(kagyouotsugu) — Nghĩa: kế nghiệp gia dình."}, {"id": 2, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[跡継ぎ]」trong ngữ cảnh: (người thừa kế, người kế vị)", "targetWord": "跡継ぎ", "correctAnswer": "あとつぎ", "options": ["ふはい", "おんしんびょうどう", "つけもの", "あとつぎ"], "explanation": "「跡継ぎ」đọc là「あとつぎ」(atotsugi) — Nghĩa: người thừa kế, người kế vị."}, {"id": 3, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[業務引き継ぎ]」trong ngữ cảnh: (bàn giao  công việc)", "targetWord": "業務引き継ぎ", "correctAnswer": "ぎょうむひきつぎ", "options": ["にこむ", "せっしやくわん", "ぎょうむひきつぎ", "いしがき"], "explanation": "「業務引き継ぎ」đọc là「ぎょうむひきつぎ」(gyoumuhikitsugi) — Nghĩa: bàn giao  công việc."}, {"id": 4, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[中継]」trong ngữ cảnh: (truyền hình trực tiếp)", "targetWord": "中継", "correctAnswer": "ちゅうけい", "options": ["ぼけつをほる", "ちゅうけい", "りこしゅぎ", "やさいをいためる"], "explanation": "「中継」đọc là「ちゅうけい」(chuukei) — Nghĩa: truyền hình trực tiếp."}, {"id": 5, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[継続する けいぞくする]」trong ngữ cảnh: (kế tục)", "targetWord": "継続する けいぞくする", "correctAnswer": "けいぞくする けいぞくする", "options": ["けいぞくする けいぞくする", "ふるさとをなつかしむ", "２０ねんらいのちき", "こい"], "explanation": "「継続する けいぞくする」đọc là「けいぞくする けいぞくする」(keizokusuru keizokusuru) — Nghĩa: kế tục."}, {"id": 6, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[後継者]」trong ngữ cảnh: (người kế thừa)", "targetWord": "後継者", "correctAnswer": "こうけいしゃ", "options": ["しんねんしゅくがかい", "なべりょうり", "ぎょうむひきつぎ", "こうけいしゃ"], "explanation": "「後継者」đọc là「こうけいしゃ」(koukeisha) — Nghĩa: người kế thừa."}, {"id": 7, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[継承する]」trong ngữ cảnh: (kế thừa)", "targetWord": "継承する", "correctAnswer": "けいしょうする", "options": ["たのみのつな", "じたくできんしんする", "けいしょうする", "すいじ"], "explanation": "「継承する」đọc là「けいしょうする」(keishousuru) — Nghĩa: kế thừa."}, {"id": 8, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[老婆]」trong ngữ cảnh: (bà lão, bà cụ)", "targetWord": "老婆", "correctAnswer": "ろうば", "options": ["ゆいごん", "ろうば", "すいじょうき", "ねんがじょう"], "explanation": "「老婆」đọc là「ろうば」(rouba) — Nghĩa: bà lão, bà cụ."}, {"id": 9, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[老婆心ながら申し上げます]」trong ngữ cảnh: (tôi rất biết ơn sự quan tâm của bạn)", "targetWord": "老婆心ながら申し上げます", "correctAnswer": "ろうばしんながらもうしあげます", "options": ["ろうばしんながらもうしあげます", "けんじょうのびとく", "かぶかがきゅうとうする", "いでんし"], "explanation": "「老婆心ながら申し上げます」đọc là「ろうばしんながらもうしあげます」(roubashinnagaramoushiagemasu) — Nghĩa: tôi rất biết ơn sự quan tâm của bạn."}, {"id": 10, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[紳士]」trong ngữ cảnh: (quý ông,lịch thiệp)", "targetWord": "紳士", "correctAnswer": "しんし", "options": ["だんちょうのおもい", "くつのなかがむれる", "こうきな", "しんし"], "explanation": "「紳士」đọc là「しんし」(shinshi) — Nghĩa: quý ông,lịch thiệp."}, {"id": 11, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[網で魚を捕る]」trong ngữ cảnh: (bắt cá bằng lưới)", "targetWord": "網で魚を捕る", "correctAnswer": "あみでさかなをとる", "options": ["あみでさかなをとる", "とくしゅかこうのぶひん", "うとい", "しゅんかん"], "explanation": "「網で魚を捕る」đọc là「あみでさかなをとる」(amidesakanaotoru) — Nghĩa: bắt cá bằng lưới."}, {"id": 12, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[網を張る]」trong ngữ cảnh: (giăng lưới)", "targetWord": "網を張る", "correctAnswer": "あみをはる", "options": ["ちくじつうやく", "いっしんいったい", "つりぼりでさかなをつる", "あみをはる"], "explanation": "「網を張る」đọc là「あみをはる」(amioharu) — Nghĩa: giăng lưới."}, {"id": 13, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[金網]」trong ngữ cảnh: (lưới sắt)", "targetWord": "金網", "correctAnswer": "かなあみ", "options": ["てのこう", "レモンをしぼる", "かなあみ", "もうぜんとたたかう"], "explanation": "「金網」đọc là「かなあみ」(kanaami) — Nghĩa: lưới sắt."}, {"id": 14, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[通信網]」trong ngữ cảnh: (mạng lưới thông tin)", "targetWord": "通信網", "correctAnswer": "つうしんもう", "options": ["かんまんなどうさ", "つうしんもう", "ひんどがたかい", "そがいかんをもつ"], "explanation": "「通信網」đọc là「つうしんもう」(tsuushinmou) — Nghĩa: mạng lưới thông tin."}, {"id": 15, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[ネクタイで首が締まる]」trong ngữ cảnh: (thắt cà vạt)", "targetWord": "ネクタイで首が締まる", "correctAnswer": "ネクタイでくびがしまる", "options": ["ネクタイでくびがしまる", "ばっぽんそくげん", "めいろうなひと", "かそのむら"], "explanation": "「ネクタイで首が締まる」đọc là「ネクタイでくびがしまる」(nekutaidekubigashimaru) — Nghĩa: thắt cà vạt."}, {"id": 16, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[首を絞める]」trong ngữ cảnh: (bóp cổ)", "targetWord": "首を絞める", "correctAnswer": "くびをしめる", "options": ["かんばしいかおり", "かんがえはかたよっている", "ぼんおどり", "くびをしめる"], "explanation": "「首を絞める」đọc là「くびをしめる」(kubioshimeru) — Nghĩa: bóp cổ."}, {"id": 17, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[レモンを絞る]」trong ngữ cảnh: (vắt chanh)", "targetWord": "レモンを絞る", "correctAnswer": "レモンをしぼる", "options": ["わこうどうじん", "きすう―ーぐうすう", "レモンをしぼる", "ゆいがどくそん"], "explanation": "「レモンを絞る」đọc là「レモンをしぼる」(remonoshiboru) — Nghĩa: vắt chanh."}, {"id": 18, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[頭を絞ってアイディアを出す]」trong ngữ cảnh: (vắt óc duy nghĩ đưa ra ý tưởng)", "targetWord": "頭を絞ってアイディアを出す", "correctAnswer": "あたまをしぼってアイディアをだす", "options": ["くびをしめる", "あたまをしぼってアイディアをだす", "きすう―ーぐうすう", "びりょう"], "explanation": "「頭を絞ってアイディアを出す」đọc là「あたまをしぼってアイディアをだす」(atamaoshibotteaideiaodasu) — Nghĩa: vắt óc duy nghĩ đưa ra ý tưởng."}, {"id": 19, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[絞殺死体]」trong ngữ cảnh: (thi thể chết ngạt)", "targetWord": "絞殺死体", "correctAnswer": "こうさつしたい", "options": ["こうさつしたい", "せんぺんばんか", "さいじょう", "うえきばち"], "explanation": "「絞殺死体」đọc là「こうさつしたい」(kousatsushitai) — Nghĩa: thi thể chết ngạt."}, {"id": 20, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[お茶をお盆に乗せる]」trong ngữ cảnh: (đặt tách trà lên khay)", "targetWord": "お茶をお盆に乗せる", "correctAnswer": "おちゃをおぼんにのせる", "options": ["ほりをめぐらす", "はんれい", "ひかげ", "おちゃをおぼんにのせる"], "explanation": "「お茶をお盆に乗せる」đọc là「おちゃをおぼんにのせる」(ochaoobonninoseru) — Nghĩa: đặt tách trà lên khay."}]}', 23, NOW());
INSERT INTO kanji_achievement_tests (stage, title, description, pass_percentage, test_data_json, display_order, created_at) VALUES
(24, 'Achievement Test 3 N1 (Chuyên đề 5・6)', 'Đề kiểm tra định kỳ Kanji Master N1 tổng hợp kiến thức Chuyên đề 5 và Chuyên đề 6 (Thang điểm 100, đạt ≥ 85% để qua chặng).', 85, '{"level": "N1", "chapters": [5, 6], "totalPoints": 100, "timeLimitMinutes": 25, "questions": [{"id": 1, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[亡き母を慕う]」trong ngữ cảnh: (tưởng nhớ về người mẹ đã mất)", "targetWord": "亡き母を慕う", "correctAnswer": "なきははをしたう", "options": ["なきははをしたう", "かんがいぶかい", "せいこうな", "じゅひょう"], "explanation": "「亡き母を慕う」đọc là「なきははをしたう」(nakihahaoshitau) — Nghĩa: tưởng nhớ về người mẹ đã mất."}, {"id": 2, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[敬慕の念]」trong ngữ cảnh: (khâm phục, thán phục)", "targetWord": "敬慕の念", "correctAnswer": "けいぼのねん", "options": ["きえつ", "かれい", "まんえつ", "けいぼのねん"], "explanation": "「敬慕の念」đọc là「けいぼのねん」(keibononen) — Nghĩa: khâm phục, thán phục."}, {"id": 3, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[慕情]」trong ngữ cảnh: (thầm mến, ái mộ)", "targetWord": "慕情", "correctAnswer": "ぼじょう", "options": ["ぎしんあんき", "おんしんびょうどう", "ぼじょう", "うるわしい"], "explanation": "「慕情」đọc là「ぼじょう」(bojou) — Nghĩa: thầm mến, ái mộ."}, {"id": 4, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[一人悦に入る]」trong ngữ cảnh: (tự hài lòng với bản thân)", "targetWord": "一人悦に入る", "correctAnswer": "ひとりえつにはいる", "options": ["じんこうしば", "ひとりえつにはいる", "びんしょうせい", "せんぼう"], "explanation": "「一人悦に入る」đọc là「ひとりえつにはいる」(hitorietsunihairu) — Nghĩa: tự hài lòng với bản thân."}, {"id": 5, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[喜悦]」trong ngữ cảnh: (sự vui mừng, hạnh phúc)", "targetWord": "喜悦", "correctAnswer": "きえつ", "options": ["きえつ", "せっしやくわん", "しゅんそく", "しょうせつのあらすじ"], "explanation": "「喜悦」đọc là「きえつ」(kietsu) — Nghĩa: sự vui mừng, hạnh phúc."}, {"id": 6, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[満悦]」trong ngữ cảnh: (hài lòng, mãn nguyện)", "targetWord": "満悦", "correctAnswer": "まんえつ", "options": ["たけのみじかいスカート", "うれえる", "ごび", "まんえつ"], "explanation": "「満悦」đọc là「まんえつ」(manetsu) — Nghĩa: hài lòng, mãn nguyện."}, {"id": 7, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[愉快な人]」trong ngữ cảnh: (người vui tính, người hài hước)", "targetWord": "愉快な人", "correctAnswer": "ゆかいなひと", "options": ["はいりょ", "うらむ", "ゆかいなひと", "ごび"], "explanation": "「愉快な人」đọc là「ゆかいなひと」(yukainahito) — Nghĩa: người vui tính, người hài hước."}, {"id": 8, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[愉悦]」trong ngữ cảnh: (vui sướng)", "targetWord": "愉悦", "correctAnswer": "ゆえつ", "options": ["こぼんのうなちちおや", "ゆえつ", "かんぜんとたたかう", "だいじょうぶ"], "explanation": "「愉悦」đọc là「ゆえつ」(yuetsu) — Nghĩa: vui sướng."}, {"id": 9, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[哀れな子供]」trong ngữ cảnh: (đứa trẻ đáng thương)", "targetWord": "哀れな子供", "correctAnswer": "あわれなこども", "options": ["あわれなこども", "こうさくする", "なきははをしたう", "こころがみにくいひと"], "explanation": "「哀れな子供」đọc là「あわれなこども」(awarenakodomo) — Nghĩa: đứa trẻ đáng thương."}, {"id": 10, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[哀れむ]」trong ngữ cảnh: (thương cảm)", "targetWord": "哀れむ", "correctAnswer": "あわれむ", "options": ["きじょうに振るまう", "じゅもく", "けいぼのねん", "あわれむ"], "explanation": "「哀れむ」đọc là「あわれむ」(awaremu) — Nghĩa: thương cảm."}, {"id": 11, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[文明が滅びる]」trong ngữ cảnh: (nền văn minh bị phá hủy)", "targetWord": "文明が滅びる", "correctAnswer": "ぶんめいがほろびる", "options": ["ぶんめいがほろびる", "くじらがしおをふく", "ふとうふくつ", "さぎしのかもになる"], "explanation": "「文明が滅びる」đọc là「ぶんめいがほろびる」(bunmeigahorobiru) — Nghĩa: nền văn minh bị phá hủy."}, {"id": 12, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[敵を滅ぼす]」trong ngữ cảnh: (tiêu diệt kẻ thù)", "targetWord": "敵を滅ぼす", "correctAnswer": "てきをほろぼす", "options": ["りゅうさん", "きりがこい", "しゅぶそくとう", "てきをほろぼす"], "explanation": "「敵を滅ぼす」đọc là「てきをほろぼす」(tekiohorobosu) — Nghĩa: tiêu diệt kẻ thù."}, {"id": 13, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[人類が滅亡する]」trong ngữ cảnh: (loài người diệt vong)", "targetWord": "人類が滅亡する", "correctAnswer": "じんるいがめつぼうする", "options": ["ガラスがくもる", "かや", "じんるいがめつぼうする", "でんしょばと"], "explanation": "「人類が滅亡する」đọc là「じんるいがめつぼうする」(jinruigametsubousuru) — Nghĩa: loài người diệt vong."}, {"id": 14, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[絶滅する]」trong ngữ cảnh: (tuyệt chủng)", "targetWord": "絶滅する", "correctAnswer": "ぜつめつする", "options": ["ひょうりゅうせん", "ぜつめつする", "はとにえさをやる", "ひつようなようそ"], "explanation": "「絶滅する」đọc là「ぜつめつする」(zetsumetsusuru) — Nghĩa: tuyệt chủng."}, {"id": 15, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[相続の権利が消滅する]」trong ngữ cảnh: (mất quyền thừa kế)", "targetWord": "相続の権利が消滅する", "correctAnswer": "そうぞくのけんりがしょうめつする", "options": ["そうぞくのけんりがしょうめつする", "うんさんむしょうする", "りゅうとうだびにおわる", "ぜつめつする"], "explanation": "「相続の権利が消滅する」đọc là「そうぞくのけんりがしょうめつする」(souzokunokenrigashoumetsusuru) — Nghĩa: mất quyền thừa kế."}, {"id": 16, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[仏滅]」trong ngữ cảnh: (ngày xấu, ngày không may mắn)", "targetWord": "仏滅", "correctAnswer": "ぶつめつ", "options": ["かにさされる", "じんるいがめつぼうする", "こうちょう", "ぶつめつ"], "explanation": "「仏滅」đọc là「ぶつめつ」(butsumetsu) — Nghĩa: ngày xấu, ngày không may mắn."}, {"id": 17, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[信号が点滅する]」trong ngữ cảnh: (đèn giao thông nhấp nháy)", "targetWord": "信号が点滅する", "correctAnswer": "しんごうがてんめつする", "options": ["そらがくもる", "だくりゅうにのまれる", "しんごうがてんめつする", "はちにさされる"], "explanation": "「信号が点滅する」đọc là「しんごうがてんめつする」(shingougatenmetsusuru) — Nghĩa: đèn giao thông nhấp nháy."}, {"id": 18, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[支離滅裂]」trong ngữ cảnh: (rời rạc, lủng củng)", "targetWord": "支離滅裂", "correctAnswer": "しりめつれつ", "options": ["えんがん", "しりめつれつ", "すじょうをあかす", "でんじは"], "explanation": "「支離滅裂」đọc là「しりめつれつ」(shirimetsuretsu) — Nghĩa: rời rạc, lủng củng."}, {"id": 19, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[獣道]」trong ngữ cảnh: (đường mòn)", "targetWord": "獣道", "correctAnswer": "けものみち", "options": ["けものみち", "じしゃく", "ゆうしょうけんないにはいる", "おちゃをにごす"], "explanation": "「獣道」đọc là「けものみち」(kemonomichi) — Nghĩa: đường mòn."}, {"id": 20, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[猛獣]」trong ngữ cảnh: (mãnh thú, thú dữ)", "targetWord": "猛獣", "correctAnswer": "もうじゅう", "options": ["くちすっぱくちゅういする", "きりさめがふる", "かいとうらんま", "もうじゅう"], "explanation": "「猛獣」đọc là「もうじゅう」(moujuu) — Nghĩa: mãnh thú, thú dữ."}]}', 24, NOW());
INSERT INTO kanji_achievement_tests (stage, title, description, pass_percentage, test_data_json, display_order, created_at) VALUES
(25, 'Achievement Test 4 N1 (Chuyên đề 7・8)', 'Đề kiểm tra định kỳ Kanji Master N1 tổng hợp kiến thức Chuyên đề 7 và Chuyên đề 8 (Thang điểm 100, đạt ≥ 85% để qua chặng).', 85, '{"level": "N1", "chapters": [7, 8], "totalPoints": 100, "timeLimitMinutes": 25, "questions": [{"id": 1, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[龍神]」trong ngữ cảnh: (rồng thần)", "targetWord": "龍神", "correctAnswer": "りゅうじん", "options": ["りゅうじん", "けつぎをさいたくする", "ぎょうむていけい", "かんげんする"], "explanation": "「龍神」đọc là「りゅうじん」(ryuujin) — Nghĩa: rồng thần."}, {"id": 2, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[繭から生糸をとる]」trong ngữ cảnh: (lấy sợi tơ từ kén tằm)", "targetWord": "繭から生糸をとる", "correctAnswer": "まゆからきいとをとる", "options": ["ほうれんそうをいちわかう", "はあくする", "しょうひんをおろす", "まゆからきいとをとる"], "explanation": "「繭から生糸をとる」đọc là「まゆからきいとをとる」(mayukarakiitootoru) — Nghĩa: lấy sợi tơ từ kén tằm."}, {"id": 3, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[繭糸]」trong ngữ cảnh: (sợi tơ, tơ nhân tạo)", "targetWord": "繭糸", "correctAnswer": "けんし", "options": ["けいりゅう", "すいとうこうさく", "けんし", "いっしんいったい"], "explanation": "「繭糸」đọc là「けんし」(kenshi) — Nghĩa: sợi tơ, tơ nhân tạo."}, {"id": 4, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[養蚕業]」trong ngữ cảnh: (nghề nuôi tằm)", "targetWord": "養蚕業", "correctAnswer": "ようさんぎょう", "options": ["いずるほ", "ようさんぎょう", "だけつする", "くさをかる"], "explanation": "「養蚕業」đọc là「ようさんぎょう」(yousangyou) — Nghĩa: nghề nuôi tằm."}, {"id": 5, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[蚕糸]」trong ngữ cảnh: (sợi tơ tằm)", "targetWord": "蚕糸", "correctAnswer": "さんし", "options": ["さんし", "こくるい", "ぞくする", "ゆるしをこう"], "explanation": "「蚕糸」đọc là「さんし」(sanshi) — Nghĩa: sợi tơ tằm."}, {"id": 6, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[桑の葉]」trong ngữ cảnh: (lá cây dâu)", "targetWord": "桑の葉", "correctAnswer": "くわのは", "options": ["ざいせいがうるおう", "けいこく", "ゆいがどくそん", "くわのは"], "explanation": "「桑の葉」đọc là「くわのは」(kuwanoha) — Nghĩa: lá cây dâu."}, {"id": 7, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[桑畑]」trong ngữ cảnh: (cánh đồng dâu)", "targetWord": "桑畑", "correctAnswer": "くわばたけ", "options": ["だとうせいにかける", "せんぺんばんか", "くわばたけ", "わこうどうじん"], "explanation": "「桑畑」đọc là「くわばたけ」(kuwabatake) — Nghĩa: cánh đồng dâu."}, {"id": 8, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[桑園]」trong ngữ cảnh: (vườn dâu)", "targetWord": "桑園", "correctAnswer": "そうえん", "options": ["うずまく", "そうえん", "いねをかる", "けんし"], "explanation": "「桑園」đọc là「そうえん」(souen) — Nghĩa: vườn dâu."}, {"id": 9, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[柳の枝がしなる]」trong ngữ cảnh: (cành liễu rủ xuống)", "targetWord": "柳の枝がしなる", "correctAnswer": "やなぎのえだがしなる", "options": ["やなぎのえだがしなる", "ふしん", "みずうみのかんたくじぎょう", "きてきをならす"], "explanation": "「柳の枝がしなる」đọc là「やなぎのえだがしなる」(yanaginoedagashinaru) — Nghĩa: cành liễu rủ xuống."}, {"id": 10, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[川柳を読む]」trong ngữ cảnh: (ngam thơ senryuu)", "targetWord": "川柳を読む", "correctAnswer": "せんりゅうをよむ", "options": ["はばつ", "こうけんする", "のどをうるおす", "せんりゅうをよむ"], "explanation": "「川柳を読む」đọc là「せんりゅうをよむ」(senryuuoyomu) — Nghĩa: ngam thơ senryuu."}, {"id": 11, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[蓄える]」trong ngữ cảnh: (tích trữ)", "targetWord": "蓄える", "correctAnswer": "たくわえる", "options": ["たくわえる", "かんべんする", "けんたいき", "らんがい"], "explanation": "「蓄える」đọc là「たくわえる」(takuwaeru) — Nghĩa: tích trữ."}, {"id": 12, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[貯蓄を励む]」trong ngữ cảnh: (cố gắng tiết kiệm (tiền))", "targetWord": "貯蓄を励む", "correctAnswer": "ちょちくをはげむ", "options": ["ぎしんあんき", "せいいあるたいおう", "おんしんびょうどう", "ちょちくをはげむ"], "explanation": "「貯蓄を励む」đọc là「ちょちくをはげむ」(chochikuohagemu) — Nghĩa: cố gắng tiết kiệm (tiền)."}, {"id": 13, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[疲労が蓄積する]」trong ngữ cảnh: (mệt mỏi tích tụ)", "targetWord": "疲労が蓄積する", "correctAnswer": "ひろうがちくせきする", "options": ["かんじょうをすませる", "せいじつなひと", "ひろうがちくせきする", "うそからでたまこと"], "explanation": "「疲労が蓄積する」đọc là「ひろうがちくせきする」(hirougachikusekisuru) — Nghĩa: mệt mỏi tích tụ."}, {"id": 14, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[勘がいい]」trong ngữ cảnh: (có trực giác/cảm giác tốt)", "targetWord": "勘がいい", "correctAnswer": "かんがいい", "options": ["しゃかいふくし", "かんがいい", "せっしやくわん", "げんいんをぶんせきする"], "explanation": "「勘がいい」đọc là「かんがいい」(kangaii) — Nghĩa: có trực giác/cảm giác tốt."}, {"id": 15, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[勘違いする]」trong ngữ cảnh: (phán đoán sai lầm, hiểu lầm)", "targetWord": "勘違いする", "correctAnswer": "かんちがいする", "options": ["かんちがいする", "じぎょうをおこす", "すいしんする", "きこう"], "explanation": "「勘違いする」đọc là「かんちがいする」(kanchigaisuru) — Nghĩa: phán đoán sai lầm, hiểu lầm."}, {"id": 16, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[勘定を済ませる]」trong ngữ cảnh: (thanh toán xong)", "targetWord": "勘定を済ませる", "correctAnswer": "かんじょうをすませる", "options": ["おうべいしょこく", "りんり", "かさく", "かんじょうをすませる"], "explanation": "「勘定を済ませる」đọc là「かんじょうをすませる」(kanjouosumaseru) — Nghĩa: thanh toán xong."}, {"id": 17, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[勘弁する]」trong ngữ cảnh: (khoan dung, tha thứ)", "targetWord": "勘弁する", "correctAnswer": "かんべんする", "options": ["ほことたて", "きょてん", "かんべんする", "なまけもの"], "explanation": "「勘弁する」đọc là「かんべんする」(kanbensuru) — Nghĩa: khoan dung, tha thứ."}, {"id": 18, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[委託する]」trong ngữ cảnh: (ủy thác)", "targetWord": "委託する", "correctAnswer": "いたくする", "options": ["たくわえる", "いたくする", "きょてん", "けいとをくる"], "explanation": "「委託する」đọc là「いたくする」(itakusuru) — Nghĩa: ủy thác."}, {"id": 19, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[信託銀行]」trong ngữ cảnh: (ngân hàng tin cậy được ủy thác)", "targetWord": "信託銀行", "correctAnswer": "しんたくぎんこう", "options": ["しんたくぎんこう", "いちがいにはいえない", "データをかいせきする", "こうふんする"], "explanation": "「信託銀行」đọc là「しんたくぎんこう」(shintakuginkou) — Nghĩa: ngân hàng tin cậy được ủy thác."}, {"id": 20, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[託児所]」trong ngữ cảnh: (nhà trẻ)", "targetWord": "託児所", "correctAnswer": "たくじしょ", "options": ["しゃかいのきはん", "ほんのページをくる", "はだがすける", "たくじしょ"], "explanation": "「託児所」đọc là「たくじしょ」(takujisho) — Nghĩa: nhà trẻ."}]}', 25, NOW());
INSERT INTO kanji_achievement_tests (stage, title, description, pass_percentage, test_data_json, display_order, created_at) VALUES
(26, 'Achievement Test 5 N1 (Chuyên đề 9・10)', 'Đề kiểm tra định kỳ Kanji Master N1 tổng hợp kiến thức Chuyên đề 9 và Chuyên đề 10 (Thang điểm 100, đạt ≥ 85% để qua chặng).', 85, '{"level": "N1", "chapters": [9, 10], "totalPoints": 100, "timeLimitMinutes": 25, "questions": [{"id": 1, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[魚を釣る]」trong ngữ cảnh: (câu cá)", "targetWord": "魚を釣る", "correctAnswer": "さかなをつる", "options": ["さかなをつる", "しゅっけしてそうになる", "きしゅ", "じことうすい"], "explanation": "「魚を釣る」đọc là「さかなをつる」(sakanaotsuru) — Nghĩa: câu cá."}, {"id": 2, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[甘い言葉を客を釣る]」trong ngữ cảnh: (câu khách bằng những lời nói ngọt ngào)", "targetWord": "甘い言葉を客を釣る", "correctAnswer": "あまいことばをきゃくをつる", "options": ["しゅぶそくとう", "えいがをさつえいする", "メロディをかなでる", "あまいことばをきゃくをつる"], "explanation": "「甘い言葉を客を釣る」đọc là「あまいことばをきゃくをつる」(amaikotobaokyakuotsuru) — Nghĩa: câu khách bằng những lời nói ngọt ngào."}, {"id": 3, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[お釣り]」trong ngữ cảnh: (tiền thừa)", "targetWord": "お釣り", "correctAnswer": "おつり", "options": ["ずかん", "もうじゅうをくさりにつなぐ", "おつり", "メロディをかなでる"], "explanation": "「お釣り」đọc là「おつり」(otsuri) — Nghĩa: tiền thừa."}, {"id": 4, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[釣銭]」trong ngữ cảnh: (tiền thừa)", "targetWord": "釣銭", "correctAnswer": "つりせん", "options": ["てんのうへいか", "つりせん", "とくてん", "こうたいし"], "explanation": "「釣銭」đọc là「つりせん」(tsurisen) — Nghĩa: tiền thừa."}, {"id": 5, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[写真を撮る]」trong ngữ cảnh: (chụp ảnh)", "targetWord": "写真を撮る", "correctAnswer": "しゃしんをとる", "options": ["しゃしんをとる", "かく", "ざぜんをくむ", "しゅってい"], "explanation": "「写真を撮る」đọc là「しゃしんをとる」(shashinotoru) — Nghĩa: chụp ảnh."}, {"id": 6, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[映画を撮影する]」trong ngữ cảnh: (quay phim)", "targetWord": "映画を撮影する", "correctAnswer": "えいがをさつえいする", "options": ["すいぼくが", "けんどう", "ぞくご", "えいがをさつえいする"], "explanation": "「映画を撮影する」đọc là「えいがをさつえいする」(eigaosatsueisuru) — Nghĩa: quay phim."}, {"id": 7, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[記念撮影]」trong ngữ cảnh: (chụp ảnh kỉ niệm)", "targetWord": "記念撮影", "correctAnswer": "きねんさつえい", "options": ["さかなをつる", "こぶする", "きねんさつえい", "ぞくご"], "explanation": "「記念撮影」đọc là「きねんさつえい」(kinensatsuei) — Nghĩa: chụp ảnh kỉ niệm."}, {"id": 8, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[仏像を彫る]」trong ngữ cảnh: (khắc tượng phật)", "targetWord": "仏像を彫る", "correctAnswer": "ぶつぞうをほる", "options": ["ぶつもんにはいりあまとなる", "ぶつぞうをほる", "かいとうらんま", "ばんそうこう"], "explanation": "「仏像を彫る」đọc là「ぶつぞうをほる」(butsuzouohoru) — Nghĩa: khắc tượng phật."}, {"id": 9, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[彫刻する]」trong ngữ cảnh: (điêu khắc)", "targetWord": "彫刻する", "correctAnswer": "ちょうこくする", "options": ["ちょうこくする", "じゅうおうむじん", "しゃしんをとる", "えんそうする"], "explanation": "「彫刻する」đọc là「ちょうこくする」(choukokusuru) — Nghĩa: điêu khắc."}, {"id": 10, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[彫刻のように美しい女性]」trong ngữ cảnh: (người con gái đẹp như tạc tượng)", "targetWord": "彫刻のように美しい女性", "correctAnswer": "ちょうこくのようにうつくしいじょせい", "options": ["れんさ", "かんがみ", "けいしょうをならす", "ちょうこくのようにうつくしいじょせい"], "explanation": "「彫刻のように美しい女性」đọc là「ちょうこくのようにうつくしいじょせい」(choukokunoyouniutsukushiijosei) — Nghĩa: người con gái đẹp như tạc tượng."}, {"id": 11, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[幻想を抱く]」trong ngữ cảnh: (ấp ủ ảo mộng)", "targetWord": "幻想を抱く", "correctAnswer": "げんそうをだく", "options": ["げんそうをだく", "こうしんヘルペス", "せきららにこくはくする", "のどがかわく"], "explanation": "「幻想を抱く」đọc là「げんそうをだく」(gensouodaku) — Nghĩa: ấp ủ ảo mộng."}, {"id": 12, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[幻想的な]」trong ngữ cảnh: (huyền ảo, huyễn hoặc)", "targetWord": "幻想的な", "correctAnswer": "げんそうてきな", "options": ["ぼこくのはたをふる", "きしゅ", "ひざまくら", "げんそうてきな"], "explanation": "「幻想的な」đọc là「げんそうてきな」(gensoutekina) — Nghĩa: huyền ảo, huyễn hoặc."}, {"id": 13, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[幻覚症状]」trong ngữ cảnh: (triệu chứng ảo giác)", "targetWord": "幻覚症状", "correctAnswer": "げんかくしょうじょう", "options": ["いっしんいったい", "きげんぜん", "げんかくしょうじょう", "すいせんのはな"], "explanation": "「幻覚症状」đọc là「げんかくしょうじょう」(genkakushoujou) — Nghĩa: triệu chứng ảo giác."}, {"id": 14, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[幻滅する]」trong ngữ cảnh: (vỡ mộng)", "targetWord": "幻滅する", "correctAnswer": "げんめつする", "options": ["古墳", "げんめつする", "頬っぺたがおちそうなくらいおいしい", "きょうりにかえる"], "explanation": "「幻滅する」đọc là「げんめつする」(genmetsusuru) — Nghĩa: vỡ mộng."}, {"id": 15, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[仙人]」trong ngữ cảnh: (thần tiên)", "targetWord": "仙人", "correctAnswer": "せんにん", "options": ["せんにん", "たんせき", "こうとうガン", "こんたん"], "explanation": "「仙人」đọc là「せんにん」(sennin) — Nghĩa: thần tiên."}, {"id": 16, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[水仙の花]」trong ngữ cảnh: (hoa thủy tiên)", "targetWord": "水仙の花", "correctAnswer": "すいせんのはな", "options": ["がっしょうする", "ゆいがどくそん", "せいぼ", "すいせんのはな"], "explanation": "「水仙の花」đọc là「すいせんのはな」(suisennohana) — Nghĩa: hoa thủy tiên."}, {"id": 17, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[聖母]」trong ngữ cảnh: (đức mẹ)", "targetWord": "聖母", "correctAnswer": "せいぼ", "options": ["わこうどうじん", "せんたくし", "せいぼ", "こだいぶんめいはっしょう"], "explanation": "「聖母」đọc là「せいぼ」(seibo) — Nghĩa: đức mẹ."}, {"id": 18, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[聖書]」trong ngữ cảnh: (kinh thánh)", "targetWord": "聖書", "correctAnswer": "せいしょ", "options": ["くちびるをかむ", "せいしょ", "せんたくし", "こころをおににしてこをしかる"], "explanation": "「聖書」đọc là「せいしょ」(seisho) — Nghĩa: kinh thánh."}, {"id": 19, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[オリンピックの聖火]」trong ngữ cảnh: (ngọn đuốc olympic)", "targetWord": "オリンピックの聖火", "correctAnswer": "オリンピックのせいか", "options": ["オリンピックのせいか", "せんぺんばんか", "ほおをあからめる", "まゆをひそめる"], "explanation": "「オリンピックの聖火」đọc là「オリンピックのせいか」(orinpikkunoseika) — Nghĩa: ngọn đuốc olympic."}, {"id": 20, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[悪魔]」trong ngữ cảnh: (ác ma, ma quỷ)", "targetWord": "悪魔", "correctAnswer": "あくま", "options": ["ぼひ", "わきみちにはいる", "したい", "あくま"], "explanation": "「悪魔」đọc là「あくま」(akuma) — Nghĩa: ác ma, ma quỷ."}]}', 26, NOW());
INSERT INTO kanji_achievement_tests (stage, title, description, pass_percentage, test_data_json, display_order, created_at) VALUES
(27, 'Achievement Test 6 N1 (Chuyên đề 11・12)', 'Đề kiểm tra định kỳ Kanji Master N1 tổng hợp kiến thức Chuyên đề 11 và Chuyên đề 12 (Thang điểm 100, đạt ≥ 85% để qua chặng).', 85, '{"level": "N1", "chapters": [11, 12], "totalPoints": 100, "timeLimitMinutes": 25, "questions": [{"id": 1, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[胎児]」trong ngữ cảnh: (thai nhi)", "targetWord": "胎児", "correctAnswer": "たいじ", "options": ["たいじ", "びょうきとたたかう", "くにのかんかつ", "しゃちょうのひしょ"], "explanation": "「胎児」đọc là「たいじ」(taiji) — Nghĩa: thai nhi."}, {"id": 2, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[胎教]」trong ngữ cảnh: (chăm sóc trong thời kỳ mang thai)", "targetWord": "胎教", "correctAnswer": "たいきょう", "options": ["せいみつけんさ", "ぎしんあんき", "じこうのあいさつをのべる", "たいきょう"], "explanation": "「胎教」đọc là「たいきょう」(taikyou) — Nghĩa: chăm sóc trong thời kỳ mang thai."}, {"id": 3, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[胎動]」trong ngữ cảnh: (thai nhi đạp bụng mẹ)", "targetWord": "胎動", "correctAnswer": "たいどう", "options": ["おんしんびょうどう", "こうそくする", "たいどう", "こくそする"], "explanation": "「胎動」đọc là「たいどう」(taidou) — Nghĩa: thai nhi đạp bụng mẹ."}, {"id": 4, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[角を矯めて牛を殺す]」trong ngữ cảnh: (“lợn lành chữa thành lợn què”)", "targetWord": "角を矯めて牛を殺す", "correctAnswer": "かくをためてうしをころす", "options": ["こえだめ", "かくをためてうしをころす", "れいぎただしい", "きたえる"], "explanation": "「角を矯めて牛を殺す」đọc là「かくをためてうしをころす」(kakuotameteushiokorosu) — Nghĩa: “lợn lành chữa thành lợn què”."}, {"id": 5, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[矯正する]」trong ngữ cảnh: (niềng răng)", "targetWord": "矯正する", "correctAnswer": "きょうせいする", "options": ["きょうせいする", "じっしする", "ろうすい", "そしする"], "explanation": "「矯正する」đọc là「きょうせいする」(kyouseisuru) — Nghĩa: niềng răng."}, {"id": 6, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[消耗品]」trong ngữ cảnh: (hàng hóa tiêu hao)", "targetWord": "消耗品", "correctAnswer": "しょうもうひん", "options": ["せっしやくわん", "べんかい", "れんきんじゅつ", "しょうもうひん"], "explanation": "「消耗品」đọc là「しょうもうひん」(shoumouhin) — Nghĩa: hàng hóa tiêu hao."}, {"id": 7, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[消耗する]」trong ngữ cảnh: (tiêu hao)", "targetWord": "消耗する", "correctAnswer": "しょうもうする", "options": ["じんつう", "しょうげき", "しょうもうする", "クマにおそわれる"], "explanation": "「消耗する」đọc là「しょうもうする」(shoumousuru) — Nghĩa: tiêu hao."}, {"id": 8, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[心神耗弱]」trong ngữ cảnh: (trí não chậm phát triển)", "targetWord": "心神耗弱", "correctAnswer": "しんしんこうじゃく", "options": ["さっかしょう", "しんしんこうじゃく", "しんぎする", "しょるいしんさ"], "explanation": "「心神耗弱」đọc là「しんしんこうじゃく」(shinshinkoujaku) — Nghĩa: trí não chậm phát triển."}, {"id": 9, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[摩耗したダイヤ]」trong ngữ cảnh: (lốp xe đã bị mòn)", "targetWord": "摩耗したダイヤ", "correctAnswer": "まもうしたダイヤ", "options": ["まもうしたダイヤ", "こくれんけんしょう", "にっぽんこくけんぽう", "ほうきする"], "explanation": "「摩耗したダイヤ」đọc là「まもうしたダイヤ」(mamoushitadaiya) — Nghĩa: lốp xe đã bị mòn."}, {"id": 10, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[鍛える]」trong ngữ cảnh: (rèn luyện)", "targetWord": "鍛える", "correctAnswer": "きたえる", "options": ["さぎし", "けいざいのはってんをそがいする", "さぎざい", "きたえる"], "explanation": "「鍛える」đọc là「きたえる」(kitaeru) — Nghĩa: rèn luyện."}, {"id": 11, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[謙遜する]」trong ngữ cảnh: (khiêm tốn)", "targetWord": "謙遜する", "correctAnswer": "けんそんする", "options": ["けんそんする", "きおくそうしつ", "ふか", "おうしゅう"], "explanation": "「謙遜する」đọc là「けんそんする」(kensonsuru) — Nghĩa: khiêm tốn."}, {"id": 12, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[遜色がない]」trong ngữ cảnh: (không kém hơn, không thấp hơn)", "targetWord": "遜色がない", "correctAnswer": "そんしょくがない", "options": ["もにふくする", "よいのみょうじょう", "しゅぶそくとう", "そんしょくがない"], "explanation": "「遜色がない」đọc là「そんしょくがない」(sonshokuganai) — Nghĩa: không kém hơn, không thấp hơn."}, {"id": 13, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[不遜な態度]」trong ngữ cảnh: (thái độ ngạo mạn)", "targetWord": "不遜な態度", "correctAnswer": "ふそんなたいど", "options": ["けたちがいのやすさ", "さんけたのけいさんをする", "ふそんなたいど", "じゅだくする"], "explanation": "「不遜な態度」đọc là「ふそんなたいど」(fusonnataido) — Nghĩa: thái độ ngạo mạn."}, {"id": 14, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[淘汰する]」trong ngữ cảnh: (loại bỏ)", "targetWord": "淘汰する", "correctAnswer": "とうたする", "options": ["しゅさいする", "とうたする", "しゅうせいかしょ", "るいせきあかじ"], "explanation": "「淘汰する」đọc là「とうたする」(toutasuru) — Nghĩa: loại bỏ."}, {"id": 15, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[自然淘汰]」trong ngữ cảnh: (đào thải tự nhiên)", "targetWord": "自然淘汰", "correctAnswer": "しぜんとうた", "options": ["しぜんとうた", "はつもうで", "けんやくする", "ふうさいがあがらない"], "explanation": "「自然淘汰」đọc là「しぜんとうた」(shizentouta) — Nghĩa: đào thải tự nhiên."}, {"id": 16, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[ご無沙汰しております]」trong ngữ cảnh: (đã lâu không gặp)", "targetWord": "ご無沙汰しております", "correctAnswer": "ごぶさたしております", "options": ["ふうさいがあがらない", "たんしんふにん", "とむらう", "ごぶさたしております"], "explanation": "「ご無沙汰しております」đọc là「ごぶさたしております」(gobusatashiteorimasu) — Nghĩa: đã lâu không gặp."}, {"id": 17, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[畏れる]」trong ngữ cảnh: (sợ hãi)", "targetWord": "畏れる", "correctAnswer": "おそれる", "options": ["てんぷ", "にょらいぞう", "おそれる", "かへい"], "explanation": "「畏れる」đọc là「おそれる」(osoreru) — Nghĩa: sợ hãi."}, {"id": 18, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[畏敬]」trong ngữ cảnh: (tôn kính)", "targetWord": "畏敬", "correctAnswer": "いけい", "options": ["かいとうらんま", "いけい", "はしげた", "ちょうじゅ"], "explanation": "「畏敬」đọc là「いけい」(ikei) — Nghĩa: tôn kính."}, {"id": 19, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[畏縮する]」trong ngữ cảnh: (hạ mình)", "targetWord": "畏縮する", "correctAnswer": "いしゅくする", "options": ["いしゅくする", "しんぼくをふかめる", "しもん", "じゅうおうむじん"], "explanation": "「畏縮する」đọc là「いしゅくする」(ishukusuru) — Nghĩa: hạ mình."}, {"id": 20, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[寿命]」trong ngữ cảnh: (tuổi thọ)", "targetWord": "寿命", "correctAnswer": "じゅみょう", "options": ["がんたん", "はばつ", "にょじつ", "じゅみょう"], "explanation": "「寿命」đọc là「じゅみょう」(jumyou) — Nghĩa: tuổi thọ."}]}', 27, NOW());
INSERT INTO kanji_achievement_tests (stage, title, description, pass_percentage, test_data_json, display_order, created_at) VALUES
(28, 'Achievement Test 7 N1 (Chuyên đề 13・14)', 'Đề kiểm tra định kỳ Kanji Master N1 tổng hợp kiến thức Chuyên đề 13 và Chuyên đề 14 (Thang điểm 100, đạt ≥ 85% để qua chặng).', 85, '{"level": "N1", "chapters": [13, 14], "totalPoints": 100, "timeLimitMinutes": 25, "questions": [{"id": 1, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[括弧でくくる]」trong ngữ cảnh: (đóng ngoặc)", "targetWord": "括弧でくくる", "correctAnswer": "かっこでくくる", "options": ["かっこでくくる", "すいちょく", "ようせい", "たくみのわざ"], "explanation": "「括弧でくくる」đọc là「かっこでくくる」(kakkodekukuru) — Nghĩa: đóng ngoặc."}, {"id": 2, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[凹レンズ]」trong ngữ cảnh: (thấu kính lõm)", "targetWord": "凹レンズ", "correctAnswer": "おうレンズれんず", "options": ["せんい", "かもん", "ぶんきする", "おうレンズれんず"], "explanation": "「凹レンズ」đọc là「おうレンズれんず」(ourenzurenzu) — Nghĩa: thấu kính lõm."}, {"id": 3, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[凸レンズ]」trong ngữ cảnh: (thấu kính lồi)", "targetWord": "凸レンズ", "correctAnswer": "とつレンズれんず", "options": ["いっしんいったい", "にじがかかる", "とつレンズれんず", "かいしょ‐ぎょうしょ‐そうしょ"], "explanation": "「凸レンズ」đọc là「とつレンズれんず」(totsurenzurenzu) — Nghĩa: thấu kính lồi."}, {"id": 4, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[凹凸がある]」trong ngữ cảnh: (có sự lồi lõm)", "targetWord": "凹凸がある", "correctAnswer": "おうとつがある", "options": ["わこうどうじん", "おうとつがある", "きせいのじじつ", "ゆいがどくそん"], "explanation": "「凹凸がある」đọc là「おうとつがある」(outotsugaaru) — Nghĩa: có sự lồi lõm."}, {"id": 5, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[凸凹した道]」trong ngữ cảnh: (con dường lồi lõm không bằng phẳng)", "targetWord": "凸凹した道", "correctAnswer": "でこぼこしたみち", "options": ["でこぼこしたみち", "めいど（めいど）", "せんす", "せんぺんばんか"], "explanation": "「凸凹した道」đọc là「でこぼこしたみち」(dekobokoshitamichi) — Nghĩa: con dường lồi lõm không bằng phẳng."}, {"id": 6, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[よだれが垂れる]」trong ngữ cảnh: (chảy nước dãi)", "targetWord": "よだれが垂れる", "correctAnswer": "よだれがたれる", "options": ["はしをかける", "ごふくうりば", "むねをつたえる", "よだれがたれる"], "explanation": "「よだれが垂れる」đọc là「よだれがたれる」(yodaregatareru) — Nghĩa: chảy nước dãi."}, {"id": 7, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[垂らす]」trong ngữ cảnh: (treo lủng lẳng)", "targetWord": "垂らす", "correctAnswer": "たらす", "options": ["でこぼこしたみち", "いっすんさきはやみ", "たらす", "はいかい"], "explanation": "「垂らす」đọc là「たらす」(tarasu) — Nghĩa: treo lủng lẳng."}, {"id": 8, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[雨垂れ]」trong ngữ cảnh: (giọt mưa rơi)", "targetWord": "雨垂れ", "correctAnswer": "あまだれ", "options": ["じゅきょう", "あまだれ", "むがむちゅう", "こどものいたずら"], "explanation": "「雨垂れ」đọc là「あまだれ」(amadare) — Nghĩa: giọt mưa rơi."}, {"id": 9, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[垂直]」trong ngữ cảnh: (thẳng đứng)", "targetWord": "垂直", "correctAnswer": "すいちょく", "options": ["すいちょく", "ふきん", "おんいん", "ごまあぶら"], "explanation": "「垂直」đọc là「すいちょく」(suichoku) — Nghĩa: thẳng đứng."}, {"id": 10, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[雪の塊]」trong ngữ cảnh: (đống tuyết)", "targetWord": "雪の塊", "correctAnswer": "ゆきのかたまり", "options": ["ごまあぶら", "ぼうせき", "ばっぽんそくげん", "ゆきのかたまり"], "explanation": "「雪の塊」đọc là「ゆきのかたまり」(yukinokatamari) — Nghĩa: đống tuyết."}, {"id": 11, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[一寸]」trong ngữ cảnh: (1 sun (3,03cm) đơn vị đo của nhật)", "targetWord": "一寸", "correctAnswer": "いっすん", "options": ["いっすん", "しゃくどをはかる", "だんがいする", "ぎしんあんき"], "explanation": "「一寸」đọc là「いっすん」(issun) — Nghĩa: 1 sun (3,03cm) đơn vị đo của nhật."}, {"id": 12, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[寸法を測る]」trong ngữ cảnh: (đo kích thước)", "targetWord": "寸法を測る", "correctAnswer": "すんぽうをはかる", "options": ["かいぞくばんCD", "しっき", "おんしんびょうどう", "すんぽうをはかる"], "explanation": "「寸法を測る」đọc là「すんぽうをはかる」(sunpouohakaru) — Nghĩa: đo kích thước."}, {"id": 13, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[寸前]」trong ngữ cảnh: (ngay trước khi...)", "targetWord": "寸前", "correctAnswer": "すんぜん", "options": ["せっしやくわん", "ほりょしゅうようじょ", "すんぜん", "みっかかんのゆうよをあたえる"], "explanation": "「寸前」đọc là「すんぜん」(sunzen) — Nghĩa: ngay trước khi...."}, {"id": 14, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[巻尺]」trong ngữ cảnh: (thước dây)", "targetWord": "巻尺", "correctAnswer": "まきじゃく", "options": ["ながそで", "まきじゃく", "むじゃきなひと", "はしゃ"], "explanation": "「巻尺」đọc là「まきじゃく」(makijaku) — Nghĩa: thước dây."}, {"id": 15, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[尺度を測る]」trong ngữ cảnh: (đo độ dài)", "targetWord": "尺度を測る", "correctAnswer": "しゃくどをはかる", "options": ["しゃくどをはかる", "あいぞめ", "むほん", "からだのしんまでひえる"], "explanation": "「尺度を測る」đọc là「しゃくどをはかる」(shakudoohakaru) — Nghĩa: đo độ dài."}, {"id": 16, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[縮尺する]」trong ngữ cảnh: (thu nhỏ)", "targetWord": "縮尺する", "correctAnswer": "しゅくしゃくする", "options": ["からだのしんまでひえる", "いやなやつ", "ざんぎゃくなこうい", "しゅくしゃくする"], "explanation": "「縮尺する」đọc là「しゅくしゃくする」(shukushakusuru) — Nghĩa: thu nhỏ."}, {"id": 17, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[藤の花]」trong ngữ cảnh: (hoa tử đằng)", "targetWord": "藤の花", "correctAnswer": "ふじのはな", "options": ["かけごと", "トランプにたいきんをかける", "ふじのはな", "じゃまする"], "explanation": "「藤の花」đọc là「ふじのはな」(fujinohana) — Nghĩa: hoa tử đằng."}, {"id": 18, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[藤色]」trong ngữ cảnh: (màu tím)", "targetWord": "藤色", "correctAnswer": "ふじいろ", "options": ["ぎゃくさつ", "ふじいろ", "すんぜん", "くつをはく"], "explanation": "「藤色」đọc là「ふじいろ」(fujiiro) — Nghĩa: màu tím."}, {"id": 19, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[藍色]」trong ngữ cảnh: (màu xanh lam)", "targetWord": "藍色", "correctAnswer": "あいいろ", "options": ["あいいろ", "きどあいらく", "だんちょうのおもい", "かんがいむりょう"], "explanation": "「藍色」đọc là「あいいろ」(aiiro) — Nghĩa: màu xanh lam."}, {"id": 20, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[藍染め]」trong ngữ cảnh: (nhuộm màu lam)", "targetWord": "藍染め", "correctAnswer": "あいぞめ", "options": ["せっとうはんをけんきょする", "とうのじだい", "りれきしょ", "あいぞめ"], "explanation": "「藍染め」đọc là「あいぞめ」(aizome) — Nghĩa: nhuộm màu lam."}]}', 28, NOW());
