(30, 'Achievement Test 9 N1 (Chuyên đề 17・18)', 'Đề kiểm tra định kỳ Kanji Master N1 tổng hợp kiến thức Chuyên đề 17 và Chuyên đề 18 (Thang điểm 100, đạt ≥ 85% để qua chặng).', 85, '{"level": "N1", "chapters": [17, 18], "totalPoints": 100, "timeLimitMinutes": 25, "questions": [{"id": 1, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[水の中に潜る]」trong ngữ cảnh: (trốn dưới nước)", "targetWord": "水の中に潜る", "correctAnswer": "みずのなかにもぐる", "options": ["みずのなかにもぐる", "せんざいてきなちから", "せんにゅうそうさ", "ぎしんあんき"], "explanation": "「水の中に潜る」đọc là「みずのなかにもぐる」(mizunonakanimoguru) — Nghĩa: trốn dưới nước."}, {"id": 2, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[物陰に潜む]」trong ngữ cảnh: (ẩn nấp trong vỏ bọc)", "targetWord": "物陰に潜む", "correctAnswer": "ものかげにひそむ", "options": ["おんしんびょうどう", "しいてきなかいしゃく", "せっしやくわん", "ものかげにひそむ"], "explanation": "「物陰に潜む」đọc là「ものかげにひそむ」(monokagenihisomu) — Nghĩa: ẩn nấp trong vỏ bọc."}, {"id": 3, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[潜入捜査]」trong ngữ cảnh: (điều tra thâm nhập)", "targetWord": "潜入捜査", "correctAnswer": "せんにゅうそうさ", "options": ["いちせきのふね", "かんぺきにしあげる", "せんにゅうそうさ", "やまのふもと"], "explanation": "「潜入捜査」đọc là「せんにゅうそうさ」(sennyuusousa) — Nghĩa: điều tra thâm nhập."}, {"id": 4, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[潜在的な力]」trong ngữ cảnh: (năng lực tiềm ẩn)", "targetWord": "潜在的な力", "correctAnswer": "せんざいてきなちから", "options": ["そうへき", "せんざいてきなちから", "とうなんにあう", "さわやかなえがお"], "explanation": "「潜在的な力」đọc là「せんざいてきなちから」(senzaitekinachikara) — Nghĩa: năng lực tiềm ẩn."}, {"id": 5, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[帆を上げる]」trong ngữ cảnh: (căng buồm lên)", "targetWord": "帆を上げる", "correctAnswer": "ほをあげる", "options": ["ほをあげる", "そうへき", "じこけんじよく", "だんちょうのおもい"], "explanation": "「帆を上げる」đọc là「ほをあげる」(hooageru) — Nghĩa: căng buồm lên."}, {"id": 6, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[帆船]」trong ngữ cảnh: (thuyền buồm)", "targetWord": "帆船", "correctAnswer": "はんせん", "options": ["おのでまきをわりる", "ゆうきがわく", "かんがいむりょう", "はんせん"], "explanation": "「帆船」đọc là「はんせん」(hansen) — Nghĩa: thuyền buồm."}, {"id": 7, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[順風満帆]」trong ngữ cảnh: (thuận buồm xuôi gió)", "targetWord": "順風満帆", "correctAnswer": "じゅんぷうまんぱん", "options": ["しんしなたいど", "けんざいかする", "じゅんぷうまんぱん", "こうどう"], "explanation": "「順風満帆」đọc là「じゅんぷうまんぱん」(junpuumanpan) — Nghĩa: thuận buồm xuôi gió."}, {"id": 8, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[一隻の船]」trong ngữ cảnh: (1 con thuyền)", "targetWord": "一隻の船", "correctAnswer": "いちせきのふね", "options": ["ものかげにひそむ", "いちせきのふね", "むしがわく", "あぜどう"], "explanation": "「一隻の船」đọc là「いちせきのふね」(ichisekinofune) — Nghĩa: 1 con thuyền."}, {"id": 9, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[軍艦]」trong ngữ cảnh: (tàu chiến)", "targetWord": "軍艦", "correctAnswer": "ぐんかん", "options": ["ぐんかん", "ものかげにひそむ", "ようえんなじょせい", "おんせんがわく"], "explanation": "「軍艦」đọc là「ぐんかん」(gunkan) — Nghĩa: tàu chiến."}, {"id": 10, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[連合艦隊]」trong ngữ cảnh: (hạm đội tàu chiến)", "targetWord": "連合艦隊", "correctAnswer": "れんごうかんたい", "options": ["あれちをかいこんする", "しんしにうけとめる", "あいまいなたいどをとる", "れんごうかんたい"], "explanation": "「連合艦隊」đọc là「れんごうかんたい」(rengoukantai) — Nghĩa: hạm đội tàu chiến."}, {"id": 11, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[甚だ不愉快]」trong ngữ cảnh: (cực kỳ khó chịu)", "targetWord": "甚だ不愉快", "correctAnswer": "はなはだふゆかい", "options": ["はなはだふゆかい", "しゅぶそくとう", "かんせん", "るいせん"], "explanation": "「甚だ不愉快」đọc là「はなはだふゆかい」(hanahadafuyukai) — Nghĩa: cực kỳ khó chịu."}, {"id": 12, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[勘違いも甚だしい]」trong ngữ cảnh: (đừng hiểu nhầm nhé)", "targetWord": "勘違いも甚だしい", "correctAnswer": "かんちがいもはなはだしい", "options": ["つばをのみこむ", "せきずい", "きこう", "かんちがいもはなはだしい"], "explanation": "「勘違いも甚だしい」đọc là「かんちがいもはなはだしい」(kanchigaimohanahadashii) — Nghĩa: đừng hiểu nhầm nhé."}, {"id": 13, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[甚大な被害]」trong ngữ cảnh: (thiệt hại rất nghiêm trọng)", "targetWord": "甚大な被害", "correctAnswer": "じんだいなひがい", "options": ["しいたけ", "せきついどうぶつ", "じんだいなひがい", "にいがたけん"], "explanation": "「甚大な被害」đọc là「じんだいなひがい」(jindainahigai) — Nghĩa: thiệt hại rất nghiêm trọng."}, {"id": 14, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[僅かな変化]」trong ngữ cảnh: (thay đổi nhỏ)", "targetWord": "僅かな変化", "correctAnswer": "わずかなへんか", "options": ["かいとうらんま", "わずかなへんか", "びこうをふくらませる", "かまでくさをかる"], "explanation": "「僅かな変化」đọc là「わずかなへんか」(wazukanahenka) — Nghĩa: thay đổi nhỏ."}, {"id": 15, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[僅差]」trong ngữ cảnh: (suýt soát, cách biệt nhỏ)", "targetWord": "僅差", "correctAnswer": "きんさ", "options": ["きんさ", "じゅうおうむじん", "顎関節症がくかんせつしょう", "のうにしゅようができる"], "explanation": "「僅差」đọc là「きんさ」(kinsa) — Nghĩa: suýt soát, cách biệt nhỏ."}, {"id": 16, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[食欲が旺盛]」trong ngữ cảnh: (thèm ăn)", "targetWord": "食欲が旺盛", "correctAnswer": "しょくよくがおうせい", "options": ["でんこうせっか", "へんぼうする", "せんてひっしょう", "しょくよくがおうせい"], "explanation": "「食欲が旺盛」đọc là「しょくよくがおうせい」(shokuyokugaousei) — Nghĩa: thèm ăn."}, {"id": 17, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[好奇心旺盛]」trong ngữ cảnh: (tính tò mò, hiếu kỳ)", "targetWord": "好奇心旺盛", "correctAnswer": "こうきしんおうせい", "options": ["けっこん", "なきはらす", "こうきしんおうせい", "ちょうねんてん"], "explanation": "「好奇心旺盛」đọc là「こうきしんおうせい」(koukishinousei) — Nghĩa: tính tò mò, hiếu kỳ."}, {"id": 18, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[寡占]」trong ngữ cảnh: (độc quyền)", "targetWord": "寡占", "correctAnswer": "かせん", "options": ["またわり", "かせん", "うすときね", "けんじゅう"], "explanation": "「寡占」đọc là「かせん」(kasen) — Nghĩa: độc quyền."}, {"id": 19, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[寡作な画家]」trong ngữ cảnh: (họa sĩ có ít tác phẩm)", "targetWord": "寡作な画家", "correctAnswer": "かさくながか", "options": ["かさくながか", "またわり", "にぎりこぶし", "かくせいする"], "explanation": "「寡作な画家」đọc là「かさくながか」(kasakunagaka) — Nghĩa: họa sĩ có ít tác phẩm."}, {"id": 20, "type": "READING", "question": "Chọn cách đọc Hiragana chính xác cho từ「[寡黙な人]」trong ngữ cảnh: (người hay ngượng ngùng)", "targetWord": "寡黙な人", "correctAnswer": "かもくなひと", "options": ["けんぽう", "すいとう", "いんとうがん", "かもくなひと"], "explanation": "「寡黙な人」đọc là「かもくなひと」(kamokunahito) — Nghĩa: người hay ngượng ngùng."}]}', 30, NOW());
